(229, '-<firma>', '-firma', 'firma', 'fIrmA', 'signature', 'firma', NULL),
(760, '-<frayle>', '-frayle', 'frayle', 'frAylE', 'brother', 'fray', NULL),
(633, '-<gobernador>', '-gobernador', 'gobernador', 'gObErnAdOr', 'governor', 'gobernador', NULL),
