(438, '-së#2', '-cë', 'ce', 'sE', 'cold', 'frío', NULL),
(324, '-seki', '-cequi', 'cequi', 'sEkI', 'some', 'algo', NULL),
(205, '-sekni', '-cecni', 'cecni', 'sEknI', 'in a place', 'en cierto lugar', 'This is clearly not a root; but since we have no analysis of the word we\r\nregister it - for the time being - as a complex root.\r\n'),
