(5512, '=¸A-a´-ke²a', 'A-a´-quetza', 'aaquetza', 'AAkE²A', 'continually raise & lower the head', 'alzar y bajar la cabeza a menudo', NULL, 10, 8, 1, NULL, '-ke²\r\n'),
