(2531, '=a´-A³', 'a´-Ach', 'aach', 'AA³', 'servant', 'criado', NULL, 9, 0, 0, NULL, '\r\n'),
(2532, '=a´-A³=ti', 'a´-Achti', 'aachti', 'AA³tI', 'be servant', 'ser criado', 'It may be that the prefix te (të) is obligatory with this verb, and that it\r\nis not found with any other object prefix.\r\n', 11, 4, 1, NULL, '=ti+k\r\n'),
(2533, '=a´-A³-¹i', 'a´-Ach-cui', 'aachcui', 'AA³¹I', 'gossip', 'chismear', 'It may be that the prefix te (të) is obligatory with this verb, and that it\r\nis not found with any other object prefix.\r\n', 11, 4, 1, NULL, '-¹i+k\r\n'),
(1211, '-a-ïk', '-a-ïc', 'aic', 'AIk', 'never', 'nunca', NULL, 0, 0, 5, NULL, '\r\n'),
(1013, '-ä-i²¹in+£i', '-ä-itzcuintli', 'aitzcuintli', 'AI²¹In', '\"dog\"', '\"perro\"', NULL, 4, 0, 0, NULL, '\r\n'),
(2725, '-ä-o´+£i', '-ä-o´tli', 'aotli', 'AO', 'water canal', 'canal', NULL, 0, 0, 0, NULL, '\r\n'),
(7064, '-a´=¸o´-om=pa', '-a´o´-ompa', 'aoompa', 'AOOmpA', 'silly', 'tonto', NULL, 0, 0, 0, NULL, '\r\n'),
