(1, 1, 0, 0, '', '', '$', '$BOOK=BANC', '$BOOK=BANC\r\n', '$BOOK=BANC\r\n'),
(2, 1, 5, 0, '', '', '$', '$FOLIO=5', '$FOLIO=5\r\n', '$FOLIO=5\r\n'),
(3, 1, 5, 1, '', '', '', '< Saluda el desposado Rey a su esposa recién llegada. >', 'Saluda el desposado Rey à su esposa recien llegada.*', 'The newlywed king greets his recently arrived bride:'),
(4, 1, 5, 2, '', '', '', '-ö +tikm-i´ïyö=wi=lti´ -£äka+£e -siwä-pil+le', 'O* ticmìïyöhuiltì tläcatle cihuäpille,', 'You are exhausted REV, oh human being, oh lady;'),
(5, 1, 5, 3, '', '', '', '-ka -ö +tim-a´xi=tï+koý -in +mo-³än+²in=ko', 'ca ö timàxi#4tïco in mochäntzïnco', 'you have come to arrive in your home REV,'),
(6, 1, 5, 4, '', '', '', '-in -on-kän +tokonmo=£a-´t=ö=l-³iya=li=lï+s -in -£äka+£ -in +to-të¹i+yo -in -ilwika=wa´ -in -£äl=t-ikpa=k=e´', 'in oncän toconmotlàtölchiäli#4lïz in tläcatl in totëcuiyo in ïlhui#4ca#4 huà in tlälticpaquè.', 'where you will await REV the word of our lord, the master of heaven and earth.'),
(7, 1, 5, 5, '', '', '', '-kën +konmo-neki=ltï+s', 'Quën conmonequiltïz,', 'How will he want it REV?'),
(8, 1, 5, 6, '', '', '', '-a´-so -wel -sem-ilwi+²in£i +nimi²onno-ma´sëwi´=²inö+s', 'àço huel ce#4 mi#4lhuitzïn tli nimitzonnomàcëhuìtzinoz.', 'Maybe the whole day REV I shall deserve you REV.'),
(9, 1, 5, 7, '', '', '', '-aw -ö +amkim-i´ïyö=wi=lti+´ke´ =£a-´t=o´=ke+´e -siwä+¸pï-pil+tine', 'Auh o anquimìïyöhuiltìquè tlà tòquèe cihuäpïpïltine', 'And you PL are exhausted, oh rulers, oh ladies.'),
(10, 1, 5, 8, '', '', '', '+namë³onno-£äxi=lï+s', 'namëchonnotläxi#4lïz', 'I shall throw you down REV.'),
(11, 1, 5, 9, '', '', '', '-i£=a´ +namë³onno-kxi-nämik=ti=lï+s', 'ïtlà namëchonnocxi nämictilïz:', 'I shall make your foot meet something REV.'),
(12, 1, 5, 10, '', '', '', '-mä +ximo-kal-akï+kän -in +amo-³än+²in=ko', 'mä ximoca#4la#4quïcän in amochäntzïnco.', 'Do enter PL your PL home REV!'),
(13, 2, 0, 0, '', '', '$', '$BOOK=CAUB', '$BOOK=CAUB\r\n', '$BOOK=CAUB\r\n'),
(14, 2, 1, 0, '', '', '$', '$FOLIO=1', '$FOLIO=1\r\n', '$FOLIO=1\r\n'),
(15, 2, 1, 1, '', '', '', '-ni-kän -i´¹ili=w=ti-ka´', '¶Nican ycuiliuhtica', 'Here is written that'),
