(1993, 7, 2, 86, '', '', '', '', '< Acada collacion. > cecen tlayacapa[n].', ''),
(1994, 7, 2, 87, '', '', '', '', '< Acada canton. > cecen calnacazco. cecen calnacazpa[n].', ''),
(1995, 7, 2, 88, '', '', '', '', '< Acada casa, o cada casa. > cecen calli. cecen calpa[n].', ''),
(1996, 7, 2, 89, '', '', '', '', '< Acada ciudad. > cecem altepetl ipa[n]. cecem altepepa[n]. cecen tepepa[n]. cecem altepetl.', ''),
(1997, 7, 2, 90, '', '', '', '', '< Acada cosa redonda. > cecen tetl.', ''),
(1998, 7, 2, 91, '', '', '', '', '< Acada cosa no redonda. > cecen.', ''),
(1999, 7, 2, 92, '', '', '', '', '< Acada gente de barrio o collacion. > cecen calpulti[n].', ''),
(2000, 7, 2, 93, '', '', '', '', '< Acada linaje. > cecen tlacamecayotl.', ''),
(2001, 7, 2, 94, '', '', '', '', '< Acada passo. > atzan. achchica. çan ic nemi. {Aduerbio}', ''),
(2002, 7, 2, 95, '', '', '', '', '< Acada persona. > cecen. cecen tlacatl.', ''),
(2003, 7, 2, 96, '', '', '', '', '< Acada pie. > cecem icxitl.', ''),
(2004, 7, 2, 97, '', '', '', '', '< Acada pueblo, o en cada pueblo y ciudad. > cecem altepepan.', ''),
(2005, 7, 2, 98, '', '', '', '', '< Acada puerta. > cecen quiauatenco. cecen quiauatëpan.', ''),
(2006, 7, 2, 99, '', '', '', '', '< Acada qual, o a cada vno por s. > cece yaca.', ''),
(2007, 7, 2, 100, '', '', '', '', '< Acada vno, de cosas animadas. > cecen. cece yaca. cecemme.', ''),
(2008, 7, 2, 101, '', '', '', '', '< Acada vno de cosas inanimadas. > cecen. < vel. > cecen tetl.', ''),
(2009, 7, 2, 102, '', '', '', '', '< Acada vno de nosotros cabra su parte, o cada qual recibira su premio y galardon. > cece yaca totech aciz yn totlaxtlauil. < Et sic de alijs. >', ''),
(2010, 7, 2, 103, '', '', '', '', '< Acaecer. > mochiua.', ''),
(2011, 7, 2, 104, '', '', '', '', '< Acaecida cosa. > o mochiuh.', ''),
(2012, 7, 2, 105, '', '', '', '', '< Acaecimiento subito. > a tenemachiti.', ''),
(2013, 7, 2, 106, '', '', '', '', '< Acaecer o acontecer en mi tiempo. > nopam mochiua, nopanti. nixpanti. nomatian. nixtla.', ''),
(2014, 7, 2, 107, '', '', '', '', '< Acaecida cosa assi. > tepam mochiuh. tepantic. teixpantic. tematiantic. teixtlatic.', ''),
(2015, 7, 2, 108, '', '', '', '', '< Acaecerme algo. > ytla nopan mochiua. ytla nopan vallauh. ytla nopan temo.', ''),
(2016, 7, 2, 109, '', '', '', '', '< Acanalar madera o piedra. > nitla,acaloa. nitla,uacaloa.', ''),
(2017, 7, 2, 110, '', '', '', '', '< Acanalada cosa assi. > acaltic. vacaltic. tlauacalolli.', ''),
(2018, 7, 2, 111, '', '', '', '', '< Acanalarse o acucharrarse. > copichaui.', ''),
(2019, 7, 2, 112, '', '', '', '', '< Acanalar assi. > nitla,copichoa.', ''),
(2020, 7, 2, 113, '', '', '', '', '< Acanalado ayre o viento. > mopiaçoa ehecatl.', ''),
(2021, 7, 2, 114, '', '', '', '', '< Acarrear. > nitla,çaca. nitla,çaçaca.', ''),
(2022, 7, 2, 115, '', '', '', '', '< Acarreada cosa o de acarreo. > tlaçaçactli. tlaçactli.', ''),
(2023, 7, 2, 116, '', '', '', '', '< Acarreador tal. > tlaçaçacac. tlaçacani. tlatlaçaçacani.', ''),
(2024, 7, 2, 117, '', '', '', '', '< Acarrear las alhajas de casa, quando se muda a otra parte. > nino,çaçaca.', ''),
(2025, 7, 2, 118, '', '', '', '', '< Acarreador tal. > moçaçacani.', ''),
(2026, 7, 2, 119, '', '', '', '', '< Acarreamiento assi. > neçaçacaliztli.', ''),
(2027, 7, 2, 120, '', '', '', '', '< Acarrear piedras. > nite,çaca.', '');
INSERT INTO `test17e` (`id`, `bid`, `fol`, `sno`, `fot`, `fof`, `opm`, `tra`, `pal`, `eng`) VALUES
(2028, 7, 2, 121, '', '', '', '', '< Acarreadas piedras. > tlaçactli tetl.', ''),
(2029, 7, 2, 122, '', '', '', '', '< Acarrear tierra. > ni,tlalçaçaca.', ''),
(2030, 7, 2, 123, '', '', '', '', '< Acarrear otras cosas. > nitla,çaçaca.', ''),
(2031, 7, 2, 124, '', '', '', '', '< Acarrear y meter algo en alguna parte. > nitla,cacalaquia.', ''),
(2032, 7, 2, 125, '', '', '', '', '< Acarrearr agua. > n,açaca.', ''),
(2033, 7, 2, 126, '', '', '', '', '< Acarreador de agua o açacan. > açacani.', ''),
(2034, 7, 2, 127, '', '', '', '', '< Acaso y sin pensar, acontecer me algo. > amo nonemachpan. a nonemachpan. amo yuhca teyollo.', ''),
(2035, 7, 2, 128, '', '', '', '', '< Acatar o tener respecto a otro. > nite,ixtilia, nite,ixmalhuia.', ''),
(2036, 7, 2, 129, '', '', '', '', '< Acaudalar. > nitla,ixnextia.', ''),
(2037, 7, 2, 130, '', '', '', '', '< Acaudillar. > notlan nitemana. nite,centlalia. nite,ololoa. nite,nanauatia.', ''),
(2038, 7, 2, 131, '', '', '', '', '< Acaudillada gente. > tetlan tlamanaltin. tl[a]olololtin. tlacentlaliltin.', ''),
(2039, 7, 2, 132, '', '', '', '', '< Acaudillador. > ytlan temanani. tecentlaliani. teololoani.', ''),
(2040, 7, 2, 133, '', '', '', '', '< Açacan o aguador. > anamacac. açacac. anamacani. atlacuini. atlatlacuic. atlacuic.', ''),
(2041, 7, 2, 134, '', '', '', '', '< Açada o açadon. > tlaltepuztli.', ''),
(2042, 7, 2, 135, '', '', '', '', '< Açada o coa de enzina, para labrar la tierra. > victli.', ''),
(2043, 7, 2, 136, '', '', '', '', '< Acecalar. > nitla,ixpetlaua. nitla,ixpetzoa. nitla,ichichiqui.', ''),
(2044, 7, 2, 137, '', '', '', '', '< Acecalada cosa. > tlaixpetlaualli. tlaixpetzolli. tlapetlauhtli. tlaichichictli.', ''),
(2045, 7, 2, 138, '', '', '', '', '< Acecalador. > tlaixpetlauani. tlaixpetzoani. tlaichichicqui. tlaichichiquini.', ''),
(2046, 7, 2, 139, '', '', '', '', '< Acecaladura. > tlaixpetlaualiztli. tlaixpetzoliztli. tlaichichiquiliztli.', ''),
(2047, 7, 2, 140, '', '', '', '', '< Acechar. busca asechar. >', ''),
(2048, 7, 2, 141, '', '', '', '', '< Acelerarse. busca enojarse. >', ''),
(2049, 7, 2, 142, '', '', '', '', '< Acelerarse, dar se priessa. > ni,iciui. nino,mociuia.', ''),
(2050, 7, 2, 143, '', '', '', '', '< Acelerado assi. > yciuhqui. momociuiani. mocipul. mucipul. { Acele }', ''),
(2051, 7, 3, 0, '', '', '$', '', '$FOLIO=3   { A ANTE C. 3 }', ''),
(2052, 7, 3, 1, '', '', '', '', '< Aceleramiento. > yciuiliztli. nemociuiliztli.', ''),
(2053, 7, 3, 2, '', '', '', '', '< Acepillar. > nitla,ixpetlaua. nitla,ichichiqui. nitla,ixpetzoa.', ''),
(2054, 7, 3, 3, '', '', '', '', '< Acepillada cosa. > tlaixpetlaualli. tlaixpetlauhtli. tlaichichictli.', ''),
(2055, 7, 3, 4, '', '', '', '', '< Acepillador. > tlaixpetlauani. tlaichichiquini.', ''),
(2056, 7, 3, 5, '', '', '', '', '< Acepilladura. > tlaixpetlaualiztli. tlaichichiquiliztli.', ''),
(2057, 7, 3, 6, '', '', '', '', '< Acepilladuras o aserraduras. > quauhtextli. quauhçoneualli.', ''),
(2058, 7, 3, 7, '', '', '', '', '< Acepilladuras largas. > quauhtlaçoneualli. quauhximalli. tlaçoneualli. tlaximalli.', ''),
(2059, 7, 3, 8, '', '', '', '', '< Acepillar algo a otro. > nite,ixcopitzalhuia.', ''),
(2060, 7, 3, 9, '', '', '', '', '< Aceptar peticion. > nitla,uelcaqui.', ''),
(2061, 7, 3, 10, '', '', '', '', '< Aceptada peticion. > tlauelcactli.', ''),
(2062, 7, 3, 11, '', '', '', '', '< Aceptar persona. > nite,ixitta.', ''),
(2063, 7, 3, 12, '', '', '', '', '< Aceptacion de personas. > teixittaliztli.', ''),
(2064, 7, 3, 13, '', '', '', '', '< Aceptador tal. > teixittani.', ''),
(2065, 7, 3, 14, '', '', '', '', '< Acequia. > tlalatlauhtli. aquetzalli. veiapantli. apantli.', ''),
(2066, 7, 3, 15, '', '', '', '', '< Acequias donde se suelen bañar algunos. > nealtilatl.', ''),
(2067, 7, 3, 16, '', '', '', '', '< Acerca de alguno. > tetlan. te[t]loc. tenauac.', ''),
(2068, 7, 3, 17, '', '', '', '', '< Acercarse a la posada el caminante. > ye nonaci. ye nonacitiuh. ye itech nonaci. ye itech nipachiui.', ''),
(2069, 7, 3, 18, '', '', '', '', '< Acercado assi. > ye ytech onacini.', ''),
(2070, 7, 3, 19, '', '', '', '', '< Acercamiento tal. > tetech onaxitiuiliztli.', ''),
(2071, 7, 3, 20, '', '', '', '', '< Acercarse a algo. > ye itech nonaci.', ''),
(2072, 7, 3, 21, '', '', '', '', '< Acertar en lo que le dize o haze. > nitla,ipantilia. ypä niauh. nitla,ipantia.', ''),
(2073, 7, 3, 22, '', '', '', '', '< Acertada cosa assi. > tlaipantililli.', ''),
(2074, 7, 3, 23, '', '', '', '', '< Acertadamente. > tlaipantililiztica.', ''),
(2075, 7, 3, 24, '', '', '', '', '< Acertamiento. > tlaipantililiztli.', ''),
(2076, 7, 3, 25, '', '', '', '', '< Acertar y tener buena dicha. > ypan naci. niquipantilia. ypan nopoa.', ''),
(2077, 7, 3, 26, '', '', '', '', '< Acertamiento assi. > ypan axiliztli.', ''),
(2078, 7, 3, 27, '', '', '', '', '< Acertar a lo que se tira. > vel ipan nicuica. vel ypan yauh. vel ipan nictlaxilia.', ''),
(2079, 7, 3, 28, '', '', '', '', '< Acertada cosa assi. > vel ipan tlauictli.', ''),
(2080, 7, 3, 29, '', '', '', '', '< Acertador tal. > vel ipan tlauicani.', ''),
(2081, 7, 3, 30, '', '', '', '', '< Acertamiento assi. > vel ipan tlauicaliztli.', ''),
(2082, 7, 3, 31, '', '', '', '', '< Acertar o hallar lo que se busca. > nitla,uelipantilia.', ''),
(2083, 7, 3, 32, '', '', '', '', '< Acertar en los negocios. > vel ninochiua.', ''),
(2084, 7, 3, 33, '', '', '', '', '< Acertador. > vel mochiuani.', ''),
(2085, 7, 3, 34, '', '', '', '', '< Acertamiento tal. > vel nechiualiztli.', ''),
(2086, 7, 3, 35, '', '', '', '', '< Acetre de agua bendita. > tlateochiualapaztli.', ''),
(2087, 7, 3, 36, '', '', '', '', '< Aceuilarse o apocarse. > nino,maceualquixtia. nin,auilquixtia.', ''),
(2088, 7, 3, 37, '', '', '', '', '< Aceuilado. > maceualquizqui. mauilquixtiani. mauilquixtiqui.', ''),
(2089, 7, 3, 38, '', '', '', '', '< Acezar. > nihcica.', ''),
(2090, 7, 3, 39, '', '', '', '', '< Acezar o carlear el perro. > neneciui.', ''),
(2091, 7, 3, 40, '', '', '', '', '< Achacar algo a otro. > tetech nitlatlamia.', ''),
(2092, 7, 3, 41, '', '', '', '', '< Achacoso ser. > a ninonotztlani. a notech ninaxitlani. ayachi noconnectica.', ''),
(2093, 7, 3, 42, '', '', '', '', '< Achacoso assi. > amo notzallani. ayachi connectieni.', ''),
(2094, 7, 3, 43, '', '', '', '', '< Achaque. > ytla ytech netlamiliztli.', ''),
(2095, 7, 3, 44, '', '', '', '', '< Achaques poner escusandose. > itla ytech ninotlamia nicnotlaneuia.', ''),
(2096, 7, 3, 45, '', '', '', '', '< Achacoso assi. > ytla itech motlamiani. quimotlaneuiani.', ''),
(2097, 7, 3, 46, '', '', '', '', '< Achicar algo. > nitla,tepitonoa. nitla,tepitilia. nitla,piciloa. nitla,ilochtia.', ''),
(2098, 7, 3, 47, '', '', '', '', '< Achicar obra. busca acortar. >', ''),
(2099, 7, 3, 48, '', '', '', '', '< Acidentalmente. busca acaso. >', ''),
(2100, 7, 3, 49, '', '', '', '', '< Aclarar el tiempo. > ye tlachipaua. ye tlachipauatimani. tlayeccanti. ye tlaqualcanti. tlachipaua. tlaneci tlanaliui. vellamani. tlacalani. {Preterito.} o tlanaliuhta. o tlacalanta. o tlaneztimoman. o tlachipauac o tlaztayac. yn ylhuicac. < i. a aclarado o aseserenado el tiempo, despues de auer passado el aguacero. >', ''),
(2101, 7, 3, 50, '', '', '', '', '< Aclarar el alua o amanecer. > ye tlaztaya.', ''),
(2102, 7, 3, 51, '', '', '', '', '< Aclararse y asentarse qualquiera licor que estaua turbio v rebuelto. > chipaua. yectia.', ''),
(2103, 7, 3, 52, '', '', '', '', '< Aclarado licor. > tlachipaualli. tlachipauhtli. tlayectilli.', ''),
(2104, 7, 3, 53, '', '', '', '', '< Acocear a otro o tirar coz o coces. > nite,telicça. nite,tetelicça. nite,cemicxotla.', ''),
(2105, 7, 3, 54, '', '', '', '', '< Acoceado. > tlatetelicçalli. tlatelicçalli.', ''),
(2106, 7, 3, 55, '', '', '', '', '< Acoceador. > tetelicçani. tetetelicçani.', ''),
(2107, 7, 3, 56, '', '', '', '', '< Acoceando o dando y tirando coces. > tetelicçaliztica.', ''),
(2108, 7, 3, 57, '', '', '', '', '< Acoceamiento. > tetelicçaliztli.', ''),
