(2112, 7, 3, 61, '', '', '', '', '< Acometido desta manera. > tlanempeualtilli. tlaixnëpeualtilli. tlaixpeualtilli.', ''),
(2113, 7, 3, 62, '', '', '', '', '< Acometimiento tal. > tenempeualtiliztli. teixnempeualtiliztli. teixpeualtiliztli.', ''),
