(2115, 7, 3, 64, '', '', '', '', '< Acometedor tal. > oquicheuani.', ''),
(2116, 7, 3, 65, '', '', '', '', '< Acometimiento assi. > oquicheualiztli.', ''),
(2117, 7, 3, 66, '', '', '', '', '< Acometer o dar ocasion a otro de reñir y contender. > nite,peualtia. nite,pepeualtia.', ''),
(2118, 7, 3, 67, '', '', '', '', '< Acometedor. > tepeualtiani. tepepeualtiani.', ''),
(2119, 7, 3, 68, '', '', '', '', '< Acometido assi. > tlapeualtilli. tlapepeualtilli.', ''),
(2120, 7, 3, 69, '', '', '', '', '< Acometimiento tal. > tepeualtiliztli. tepepeualtiliztli.', ''),
(2121, 7, 3, 70, '', '', '', '', '< Acompañar a alguno estando con el en su casa. > {&c.} tetlan nica.', ''),
(2122, 7, 3, 71, '', '', '', '', '< Acompañado assi. > ytlan yeloac. ytlan onoac.', ''),
(2123, 7, 3, 72, '', '', '', '', '< Acompañador tal. > tetlan yeni. tenauac yeni.', ''),
(2124, 7, 3, 73, '', '', '', '', '< Acompañamiento assi. > tetlan yeliztli. tenauac yeliztli. { a 3 Acompa- } { A ANTE C. }', ''),
