(2133, 7, 3, 82, '', '', '', '', '< Acompañado assi. > oncaualo. oncaualoni. ont[l](i)aaxiltilli.', ''),
(2134, 7, 3, 83, '', '', '', '', '< Acompañador tal. > ontecauani.', ''),
(2135, 7, 3, 84, '', '', '', '', '< Acompañamiento assi. > ontecaualiztli.', ''),
(2136, 7, 3, 85, '', '', '', '', '< Acompañar a otro desde su casa. > nonteana.', ''),
(2137, 7, 3, 86, '', '', '', '', '< Acompañado assi. > ontlaantli. ontlaanalli.', ''),
(2138, 7, 3, 87, '', '', '', '', '< Acompañador tal. > onteanani. onteanqui.', ''),
(2139, 7, 3, 88, '', '', '', '', '< Acompañamiento assi. > onteanaliztli.', ''),
(2140, 7, 3, 89, '', '', '', '', '< Acompañar a la nouia el pariente o deudo della. > nite,ciuamoncaua.', ''),
(2141, 7, 3, 90, '', '', '', '', '< Acompañador assi. > teciuamoncauhqui.', ''),
(2142, 7, 3, 91, '', '', '', '', '< Acompañadores desta manera. > teciuamoncauhque.', ''),
(2143, 7, 3, 92, '', '', '', '', '< Acompañamiento tal. > teciuamoncaualiztli.', ''),
(2144, 7, 3, 93, '', '', '', '', '< Acompañar con buenas obras la fee. > quallachiualiztli nicuicaltia yn tlaneltoquiliztli. quallachiualiztli nictoctia yn notlaneltoquiliz. quallachiualiztli yc malintiuh yc ilacatziuhtiuh yn notlaneltoquiliz.', ''),
(2145, 7, 3, 94, '', '', '', '', '< Aconsejar. > nitla,nanamiqui. nitla,tlatolnanamiqui. tenacaztitech ninopiloa. {Metapho.} nite,nanauatia.', ''),
