(2150, 7, 3, 99, '', '', '', '', '< Acordarme de algo. > ni,tlalnamiqui.', ''),
(2151, 7, 3, 100, '', '', '', '', '< Acordar algo a otro. > nite,tlalnamictia. nitla,tlalnamictia.', ''),
