(2182, 7, 3, 131, '', '', '', '', '< Açotado. > tlamecauitectli.', ''),
(2183, 7, 3, 132, '', '', '', '', '< Açotador. > temecauitequini.', ''),
(2184, 7, 3, 133, '', '', '', '', '< Açotarse. > nino,mecauitequi.', ''),
