(2186, 7, 3, 135, '', '', '', '', '< Açote de cuerda o diciplina. > mecatl. temecauiteconi.', ''),
(2187, 7, 3, 136, '', '', '', '', '< Açotea o açutea. > tlapantli.', ''),
