(2189, 7, 3, 138, '', '', '', '', '< Acrecentada cosa. > tlatlapiuilli. tlamiequililli.', ''),
(2190, 7, 3, 139, '', '', '', '', '< Acrecentador assi. > tlatlapiuiani. tlamiequiliani.', ''),
(2191, 7, 3, 140, '', '', '', '', '< Acrecentamiento desta manera. > tlatlapiuiliztli. tlamiequiliztli.', ''),
(2192, 7, 3, 141, '', '', '', '', '< Acrecentar a otro la enfermedad. > nite,cocoliztlapiuilia. nite,tlanalhuia. nite,tlanauitia. nite,tla(na)nauiltia. nite,cocolilochtia.', ''),
