(2194, 7, 4, 0, '', '', '$', '', '$FOLIO=4   { A ANTE C, ET D. 4 }', ''),
(2195, 7, 4, 1, '', '', '', '', '< Acucharrada cosa. > copichtic.', ''),
(2196, 7, 4, 2, '', '', '', '', '< Acucharrarse algo. > copichaui.', ''),
(2197, 7, 4, 3, '', '', '', '', '< Acuchillar a otro. > nite,tepuzmacquauhuia.', ''),
(2198, 7, 4, 4, '', '', '', '', '< Acuchillarse con otros. > teuan nitetepuzmacquauhuia.', ''),
