(2219, 7, 4, 25, '', '', '', '', '< Aceuilado. > mauilquixti. mauilquixtiani. mauilquixtiqui.', ''),
(2220, 7, 4, 26, '', '', '', '', '< Açutea. > tlapantli.', ''),
