(2240, 7, 4, 46, '', '', '', '', '< Adelgazamiento tal. > tlacanaualiztli.', ''),
(2241, 7, 4, 47, '', '', '', '', '< Adelgazar hilo o cosas largas y rollizas o cätar cö boz delgada y mugeril. > nitlapitzaua.', ''),
(2242, 7, 4, 48, '', '', '', '', '< Adelgazada cosa assi. > tlapitzaualli. tlapitzauhtli.', ''),
(2243, 7, 4, 49, '', '', '', '', '< Adelgazamiento tal. > tlapitzaualiztli.', ''),
