(2251, 7, 4, 57, '', '', '', '', '< Adentelladura tal. > tetlancotonaliztli.', ''),
(2252, 7, 4, 58, '', '', '', '', '< Adereçar o adornar algo. > nitla,chichiua. nitla,cencaua.', ''),
(2253, 7, 4, 59, '', '', '', '', '< Adereçarse. > nino,chichiua. nino,cencaua.', ''),
(2254, 7, 4, 60, '', '', '', '', '< Adereçada cosa. > tlachichiuhtli. tlacencauhtli. tlacencaualli.', ''),
(2255, 7, 4, 61, '', '', '', '', '< Adereço tal. > tlachichiualiztli. tlacencaualiztli.', ''),
(2256, 7, 4, 62, '', '', '', '', '< Adereçarse o polirse y componerse. > nin,ihimati. nino,chichiua.', ''),
(2257, 7, 4, 63, '', '', '', '', '< Adereçar a otro assi. > nite,chichiua.', ''),
(2258, 7, 4, 64, '', '', '', '', '< Adereço tal. > techichiualiztli. nechichiualiztli.', ''),
(2259, 7, 4, 65, '', '', '', '', '< Adereçar y adornar algo honrosamente. > nitla,mauichichiua. nitla,yecchichiua.', ''),
(2260, 7, 4, 66, '', '', '', '', '< Adereçada cosa assi. > tlamauichichiuhtli. tlayecchichiuhtli.', ''),
(2261, 7, 4, 67, '', '', '', '', '< Adereço tal. > tlamauichichiualiztli. tlayecchichiualiztli.', ''),
(2262, 7, 4, 68, '', '', '', '', '< Adereçarse y componerse para ser codiciado de las mugeres. > nitla,ixami. { a 4 Adere } { A ANTE D. }', ''),
(2263, 7, 4, 69, '', '', '', '', '< Adereçado assi. > tlaixamini.', ''),
(2264, 7, 4, 70, '', '', '', '', '< Adereçar algo para otro. > nite,tlacencauilia. < busca aparejar. >', ''),
(2265, 7, 4, 71, '', '', '', '', '< Adereçar y componer lo que esta mal puesto y desconcertado. > nitla,uelteca.', ''),
(2266, 7, 4, 72, '', '', '', '', '< Adereçada cosa assi. > tlaueltectli.', ''),
(2267, 7, 4, 73, '', '', '', '', '< Adereçador tal. > tlaueltecani.', ''),
(2268, 7, 4, 74, '', '', '', '', '< Adereçamiento assi. > tlaueltecaliztli.', ''),
(2269, 7, 4, 75, '', '', '', '', '< Adereçado galanamente, conforme a su estado. > mopanitia.', ''),
(2270, 7, 4, 76, '', '', '', '', '< Adereçar la hoja del maguey para sacar el cerro y hazer del muchas cosas. > nitla,cima.', ''),
(2271, 7, 4, 77, '', '', '', '', '< Aderechas. > melauaca. melaualiztica.', ''),
(2272, 7, 4, 78, '', '', '', '', '< Adeseo. > a onnemaquiliztica. tlamalhuiliztica.', ''),
(2273, 7, 4, 79, '', '', '', '', '< Adesora. > a tenemachpa[n]. amo yuhca teyollo.', ''),
(2274, 7, 4, 80, '', '', '', '', '< Adeudarse tomando prestado. > nino,tlacuia.', ''),
(2275, 7, 4, 81, '', '', '', '', '< Adeudado. > motlacui.', ''),
(2276, 7, 4, 82, '', '', '', '', '< Adiestrar ciego. > nite,ana. nite,yacana.', ''),
(2277, 7, 4, 83, '', '', '', '', '< Adiestrado assi. > tlaantli. tlayacantli.', ''),
(2278, 7, 4, 84, '', '', '', '', '< Adiestrador de ciego. > teanani. teyacanani.', ''),
(2279, 7, 4, 85, '', '', '', '', '< Adiue. > coyotl.', ''),
(2280, 7, 4, 86, '', '', '', '', '< Adiue pequeño. > coyopil. coyotontli.', ''),
(2281, 7, 4, 87, '', '', '', '', '< Adiuinar sin agueros. > nitla,yolteouia. tetëpan nitlatoa.', ''),
(2282, 7, 4, 88, '', '', '', '', '< Adiuinacion tal. > tlayolteouiliztli. tetenpan tlatoliztli.', ''),
(2283, 7, 4, 89, '', '', '', '', '< Adiuino assi. > tlayolteouiani. tetempan tlatoani.', ''),
(2284, 7, 4, 90, '', '', '', '', '< Adiuinar por suertes o agueros. > ni,ticiti. ni,tlapoa.', ''),
(2285, 7, 4, 91, '', '', '', '', '< Adiuinacion assi. > ticiyotl. tlapoaliztli.', ''),
(2286, 7, 4, 92, '', '', '', '', '< Adiuino tal. > ticitl. tlapouhqui.', ''),
(2287, 7, 4, 93, '', '', '', '', '< Adiuinar en agua. > atl nicmana. atlan niteitta.', ''),
(2288, 7, 4, 94, '', '', '', '', '< Adiuinacion assi. > amanaliztli. atlan teittaliztli.', ''),
(2289, 7, 4, 95, '', '', '', '', '< Adiuino tal. > amanani. atlan teittani.', ''),
(2290, 7, 4, 96, '', '', '', '', '< Adiuinar por signos, o sueños. > ni,tonalpoa.', ''),
(2291, 7, 4, 97, '', '', '', '', '< Adiuinacion assi. > tonalpoaliztli.', ''),
(2292, 7, 4, 98, '', '', '', '', '< Adiuino desta manera. > tonalpouhqui.', ''),
(2293, 7, 4, 99, '', '', '', '', '< Administrar algo. > nite,tlamachia. nite,tlatlamachia nite,tlatlatlalilia. nite,tlamamaca.', ''),
(2294, 7, 4, 100, '', '', '', '', '< Administracion tal. > tetlamamaquiliztli. tetlatlamachiliztli. tetlatlalililiztli.', ''),
(2295, 7, 4, 101, '', '', '', '', '< Administrada cosa. > tetlamactli. tetlamachilli. tetlatlalililli.', ''),
(2296, 7, 4, 102, '', '', '', '', '< Administrador. > tetlamamacani. tetlamachiani. tetlatlamachiani. tetlatlaliliani.', ''),
(2297, 7, 4, 103, '', '', '', '', '< Admirar, escandalizar o espätar a otro. > nite,içauia. nite,mauhtia.', ''),
(2298, 7, 4, 104, '', '', '', '', '< Admirable cosa. > mauiztic. mauiçauhqui.', ''),
(2299, 7, 4, 105, '', '', '', '', '< Admiracion. > tlamauiçoliztli. neiçauiliztli.', ''),
(2300, 7, 4, 106, '', '', '', '', '< Admirado. > tlamauiço. tlamauiçoani. miçauiani.', ''),
(2301, 7, 4, 107, '', '', '', '', '< Admirarse. > nitla,mauiçoa. nin,içauia.', ''),
(2302, 7, 4, 108, '', '', '', '', '< Admitir a alguno a alguna cosa. > nite,celia. nite,nequi.', ''),
(2303, 7, 4, 109, '', '', '', '', '< Admitido. > tlacelilli. ontlanectli.', ''),
(2304, 7, 4, 110, '', '', '', '', '< Admitir lo que se dize, o haze. > nitla,paccacaqui. nitla,uelcaqui. nitla,uelitta.', ''),
(2305, 7, 4, 111, '', '', '', '', '< Admitido assi. > tlauelcactli. tlauelittalli.', ''),
(2306, 7, 4, 112, '', '', '', '', '< Adobar algo, busca adereçar. >', ''),
(2307, 7, 4, 113, '', '', '', '', '< Adobar lo que esta mal hecho. > nitla,patia. nitla,q[ua]ltilia.', ''),
(2308, 7, 4, 114, '', '', '', '', '< Adobar cueros. > nitla,yamania. ni,cuetlaxuauana. n(e)[ic],uauana.', ''),
(2309, 7, 4, 115, '', '', '', '', '< Adobado cuero. > tlayamanilli. tlauauantli. euatlauauantli.', ''),
(2310, 7, 4, 116, '', '', '', '', '< Adobador de cueros. > tlayamaniani. cuetlaxuauanqui. euauauanqui.', ''),
(2311, 7, 4, 117, '', '', '', '', '< Adobar texendo agujero de manta. > {&c.} nitla,chichi.', ''),
(2312, 7, 4, 118, '', '', '', '', '< Adobada cosa assi. > tlachichitl.', ''),
(2313, 7, 4, 119, '', '', '', '', '< Adobar ropa vieja. > nitla,nextlatia. nitla,nexquaqualatza.', ''),
(2314, 7, 4, 120, '', '', '', '', '< Adobada ropa assi. > tlanextlatilli. tlanexq^q^latzalli.', ''),
(2315, 7, 4, 121, '', '', '', '', '< Adobe de barro. > xamitl.', ''),
(2316, 7, 4, 122, '', '', '', '', '< Adobes hazer. > ni,xanchiua. ni,xancopina.', ''),
(2317, 7, 4, 123, '', '', '', '', '< Adobo. lo mesmo. >', ''),
(2318, 7, 4, 124, '', '', '', '', '< Adobo de mayz molido, conque adereçan las mätas ralas. > tlatexotl.', ''),
(2319, 7, 4, 125, '', '', '', '', '< Adonde? > can? cancuixpan? cäcuix? cäyepa? canin? campa? < Aduerbio. para preguntar. >', ''),
(2320, 7, 4, 126, '', '', '', '', '< Adöde, o en que parte del cuerpo te duele? > ca[n]yepa canyeuel ym mitzcocoa. campa ym mitzcocoa.', ''),
(2321, 7, 4, 127, '', '', '', '', '< Adonde emos de yr? > cannelpa tiazque? cannel tiazq~.', ''),
(2322, 7, 4, 128, '', '', '', '', '< Adonde estuuiere. > yn canin yez. yn campa yez.', ''),
(2323, 7, 4, 129, '', '', '', '', '< Adonde quiera, o enqualquiera lugar. > çaço can. çaço campa. nouian.', ''),
(2324, 7, 4, 130, '', '', '', '', '< Adoptar tomar por hijo. > ninote,piltzintia.', ''),
(2325, 7, 4, 131, '', '', '', '', '< Adopcion tal. > netepiltzintiliztli.', ''),
(2326, 7, 4, 132, '', '', '', '', '< Adoptiuo hijo. > netepiltzintilli.', ''),
(2327, 7, 4, 133, '', '', '', '', '< Adoquiera que. > çaço campa. {Aduerbio.} çaço cä. çaço canin.', ''),
(2328, 7, 4, 134, '', '', '', '', '< Adorar a dios. > nicno,teutia. nicno,tlatlauhtilia.', ''),
(2329, 7, 4, 135, '', '', '', '', '< Adorable dios, o digno de ser adorado. > neteotiloni. tlatlauhtiloni.', ''),
(2330, 7, 4, 136, '', '', '', '', '< Adoracion tal. > neteotiliztli. tlatlatlauhtiliztli.', ''),
(2331, 7, 4, 137, '', '', '', '', '< Adormecer al niño. > nite,cochteca.', ''),
(2332, 7, 4, 138, '', '', '', '', '< Adormecido niño. > tlacochtectli.', ''),
(2333, 7, 4, 139, '', '', '', '', '< Adormecimiento assi. > tecochtecaliztli.', ''),
(2334, 7, 4, 140, '', '', '', '', '< Adormecer a alguno con encantamiento, o en otra manera assi. > nite,cochtlaça.', ''),
(2335, 7, 4, 141, '', '', '', '', '< Adormecido assi. > tlacochtlaztli.', ''),
(2336, 7, 4, 142, '', '', '', '', '< Adormecerse, o entomecerse el pie. > nocxi cepoa. nocxi cecepoa.', ''),
(2337, 7, 4, 143, '', '', '', '', '< Adormecido pie. > cepouhqui ycxitl. cecepouhqui ycxitl.', ''),
(2338, 7, 4, 144, '', '', '', '', '< Adormecerse la mano. > no,ma cepoa. no,ma cecepoa.', ''),
(2339, 7, 4, 145, '', '', '', '', '< Adormecida mano. > cepouhqui maitl. cecepouhqui maitl. < y assi se dize delos demas miembros del cuerpo. >', ''),
(2340, 7, 4, 146, '', '', '', '', '< Adormecerse, o entomecerse otro qualquier miëbro del cuerpo. > cepoa.', ''),
(2341, 7, 4, 147, '', '', '', '', '< Adormecido miembro. > cepoctic. cecepoctic. cecepouhqui. cepouhqui.', ''),
(2342, 7, 4, 148, '', '', '', '', '< Adornar. busca componer. > nitla,mauichichiua. { Adqui }', ''),
(2343, 7, 5, 0, '', '', '$', '', '$FOLIO=5   { A ANTE D. E, ET, F 5 }', ''),
(2344, 7, 5, 1, '', '', '', '', '< Adquirir con trabajo lo necessario a la vida. > a nicaxcauia. nitla,tlapaliuhcauia. nicoquichuia. quiciaui. quihiouia, ic toneua yc chichinaca yn noyollo yn nonacayo. nic,ciaui.', ''),
(2345, 7, 5, 2, '', '', '', '', '< Adrede dezir o hazer algo. > yc nitequeloa. çan ic ninoqueloa. çan iuh nicchiua. yc ninotecoa.', ''),
(2346, 7, 5, 3, '', '', '', '', '< Aduenedizo. > vecatlacatl. veca valeua. veca chane. toueyo.', ''),
(2347, 7, 5, 4, '', '', '', '', '< Aduenedizos ya auezindados. > tlacanechicolti[n]. tlacanepapanti[n].', ''),
(2348, 7, 5, 5, '', '', '', '', '< Aduertir a o otro, paraque ande sobreauiso en lo q~ le conuiene. > yc ni,xonexca. yc nitla,matzoa.', ''),
(2349, 7, 5, 6, '', '', '', '', '< Aduiento. > vallaliztli.', ''),
(2350, 7, 5, 7, '', '', '', '', '< Adufle para tañer las mugeres. > euaueuetl.', ''),
(2351, 7, 5, 8, '', '', '', '', '< Adular. busca lisongear. > nite,chachamaua. {&c.} nite,mamachotla.', ''),
(2352, 7, 5, 9, '', '', '', '', '< Adulador. > techachamauani.', ''),
(2353, 7, 5, 10, '', '', '', '', '< Adulacion. > techachamaualiztli.', ''),
(2354, 7, 5, 11, '', '', '', '', '< Adulterar. > nite,tlaxima. tepan niauh. nic,maxaloa yn nonamic.', ''),
(2355, 7, 5, 12, '', '', '', '', '< Adulterino o adulterina. busca bastardo. >', ''),
(2356, 7, 5, 13, '', '', '', '', '< Adulterio. > tetlaximaliztli. tepan yaliztli.', ''),
(2357, 7, 5, 14, '', '', '', '', '< Adultero o adultera. > tetlaximani. tetlaxinqui. tepä yani. tepan yaqui.', ''),
(2358, 7, 5, 15, '', '', '', '', '< A Ello, sus compañeros, ea ea a ello. > tla ye cuel. ma ye cuele. ma cuele.', ''),
(2359, 7, 5, 16, '', '', '', '', '< Aempuxones. > tetotopeualiztica. teixicquetzaliztica. teixcuecuetlanaliztica.', ''),
(2360, 7, 5, 17, '', '', '', '', '< Aescondidas. busca escondidamente. >', ''),
(2361, 7, 5, 18, '', '', '', '', '< Aessotra parte, o a essotra vanda. > ye nepa.', ''),
(2362, 7, 5, 19, '', '', '', '', '< Aesta hora. > ymmani[n].', ''),
(2363, 7, 5, 20, '', '', '', '', '< A este tiempo, o aeste mismo tiempo. > ye axcan. ye no yquacy[n]. ye no uel axcan.', ''),
(2364, 7, 5, 21, '', '', '', '', '< AFable persona. > muchi tlacatl ytlaço. muchi tlacatl ycniuh. tecemicniuh.', ''),
(2365, 7, 5, 22, '', '', '', '', '< Afabilidad. > tecemicniuhyotl.', ''),
(2366, 7, 5, 23, '', '', '', '', '< Afamarse. > ni,tenyoa. ni,mauiçoa. nino,tenyotia.', ''),
(2367, 7, 5, 24, '', '', '', '', '< Afamar a otro. > nite,tenyotia. nite,mauiçotia.', ''),
(2368, 7, 5, 25, '', '', '', '', '< Afear y estragar lo hermoso. > nitla,ytlacoa.', ''),
(2369, 7, 5, 26, '', '', '', '', '< Afeada cosa assi. > tlaitlacolli.', ''),
(2370, 7, 5, 27, '', '', '', '', '< Afeitarse la muger a su modo antiguo. > nino,xaua.', ''),
(2371, 7, 5, 28, '', '', '', '', '< Afeitada assi. > tlaxaualli. tlaxauhtli, xauhqui.', ''),
(2372, 7, 5, 29, '', '', '', '', '< Afeite tal. > xaualli. nexaualoni.', ''),
(2373, 7, 5, 30, '', '', '', '', '< Afeitarse los hombres al modo antiguo. > nin,ichichiua.', ''),
(2374, 7, 5, 31, '', '', '', '', '< Afeite assi. > neichichiualoni. neichichiualli. xaualli.', ''),
(2375, 7, 5, 32, '', '', '', '', '< Afeitarse la cara. > nin,ichichiua.', ''),
(2376, 7, 5, 33, '', '', '', '', '< Afeitar a otro assi. > nite,ichichiua.', ''),
(2377, 7, 5, 34, '', '', '', '', '< Afeitador tal. > teichichiuani.', ''),
(2378, 7, 5, 35, '', '', '', '', '< Afeitamiento assi. > teichichiualiztli.', ''),
(2379, 7, 5, 36, '', '', '', '', '< Afeitar o rapar y tresquilar el cabello. > nite,xima.', ''),
(2380, 7, 5, 37, '', '', '', '', '< Afeitado assi, tlaxintli. >', ''),
(2381, 7, 5, 38, '', '', '', '', '< Afeitar barua a otro. > nite,tentzo[n]xima.', ''),
(2382, 7, 5, 39, '', '', '', '', '< Afeitado assi. > tlatentzonxintli.', ''),
(2383, 7, 5, 40, '', '', '', '', '< Afeminado. > ciuayollo. a yollo tlapaltic. a oquichyollo.', ''),
(2384, 7, 5, 41, '', '', '', '', '< Aficionarse o aplicarse a algo. > ytla itech nino,mati. ytla ytech vetzi(n) noyollo. ytech ninomati. niquicelia. tetech ninomati.', ''),
(2385, 7, 5, 42, '', '', '', '', '< Aficionado assi. > ytla ytech momatqui. tetech momati. ytla ytech vetzi yyullo.', ''),
(2386, 7, 5, 43, '', '', '', '', '< Aficionado a mugeres, y no en mala parte. > ciuaimpach. ciuanemilice. ciuatlaçoua.', ''),
(2387, 7, 5, 44, '', '', '', '', '< Afilar cosa de hierro. > nitla,tentia. nitla,tenitztia.', ''),
(2388, 7, 5, 45, '', '', '', '', '< Afilar espada o cosa de dos filos. > nitla,necoctentia. nitla,necoctenitztia.', ''),
(2389, 7, 5, 46, '', '', '', '', '< Afilada cosa. > tlatentilli. tlatenitztilli. tlanecoctentilli. tlanecoctenitztilli.', ''),
(2390, 7, 5, 47, '', '', '', '', '< Afilador. > tlatenti. tlatentiani. tlatenitzti. tlatenitztiani. tlanecoctentiani. tlanecoctenitztiani.', ''),
(2391, 7, 5, 48, '', '', '', '', '< Afiladura. > tlatentiliztli. tlatenitztiliztli. tlanecoctëtiliztli. tlanecocitztentiliztli.', ''),
(2392, 7, 5, 49, '', '', '', '', '< Afinar algo. > nitla,chipaua. nitla,yectia. nitla,qualtilia.', ''),
(2393, 7, 5, 50, '', '', '', '', '< Afirmar algo. > nitla,neltilia. nitla,nelitoa.', ''),
(2394, 7, 5, 51, '', '', '', '', '< Afirmacion. > tlaneltililiztli. tlanelitoliztli.', ''),
(2395, 7, 5, 52, '', '', '', '', '< Afirmada cosa. > tlaneltililli. tlanelitolli.', ''),
(2396, 7, 5, 53, '', '', '', '', '< Afirmadamente. > tlaneltililiztica. tlanelitoliztica.', ''),
(2397, 7, 5, 54, '', '', '', '', '< Afirmar con atreuimiento y porfia. > nino,tenquauhtilia. nino,tlatolchicaua. nino,tentlapaltilia.', ''),
(2398, 7, 5, 55, '', '', '', '', '< Afirmacion tal. > netenquauhtiliztli. netlatolchicaualiztli. netentlapaltiliztli.', ''),
(2399, 7, 5, 56, '', '', '', '', '< Afirmada cosa assi. > tlatenquauhtililli. tlatentlapaliuhcauilli.', ''),
(2400, 7, 5, 57, '', '', '', '', '< Afirmadamente. > tlatenquauhtiliztica. netenquauhtiliztica. tlatentlapaliuhcauiliztica. netentlapaliuhcauiliztica.', ''),
(2401, 7, 5, 58, '', '', '', '', '< Afligir o fatigar a otro. > nite,tolinia. nite,tequipachoa. nite,yollotoneua. nite,yolpatzmictia. nite,cococapoloa. cococ teopouhqui nicteittitia. nite,atlamachtia.', ''),
(2402, 7, 5, 59, '', '', '', '', '< Aflicion o afligimiento. > tetoliniliztli. tetequipacholiztli. tecococapololiztli. teatlamachtiliztli.', ''),
(2403, 7, 5, 60, '', '', '', '', '< Afligido. > tlatolinilli. tlatequipacholli. tlacococapololli. tlaatlamachtilli. yollotoneuhqui.', ''),
(2404, 7, 5, 61, '', '', '', '', '< Afligidor. > tetoliniani. tetequipachoani. tecococapoloani. ateatlamachtiani.', ''),
(2405, 7, 5, 62, '', '', '', '', '< Afligir mucho a otro. > nite,ellelaxitia. nite,toneua. nite,chichinatza. nite,atlamachtia. nite,tlaciauiltia. nite,nentlamachtia. nite,chichinacapoloa.', ''),
(2406, 7, 5, 63, '', '', '', '', '< Aflicion tal. > teellelaxitiliztli. tetoneualiztli. techichinatzaliztli. teatlamachtiliztli. tetlaciauiltiliztli. yolactiuechiliztli. techichinacapololiztli.', ''),
(2407, 7, 5, 64, '', '', '', '', '< Afligido assi. > tlaellelaxitilli. tlatoneualli. tlachichinatztli, tlaatlamachtilli. yolpatzmicqui. tlatlaciauiltilli. moyoltequipachoani. tlachichinacapololli.', ''),
(2408, 7, 5, 65, '', '', '', '', '< Afligidor desta manera. > teellelaxiti. teellelaxitiani. tetoneuani. techichinatzani. ateatlamachtiani. tetlaciauiltiani. techichinacapoloani.', ''),
(2409, 7, 5, 66, '', '', '', '', '< Afligido estar de algun dolor o escozimiento corporal. > nino,tlalteuhnemitia. { Aflicion } { A ANTE F, ET G. }', ''),
(2410, 7, 5, 67, '', '', '', '', '< Aflicion tal. > teellelaxitiliztli. tetoneualiztli. techichinatzaliztli. teatlamachtiliztli. tetlaciauiltiliztli. yolactiuechiliztli. techichinacapololiztli.', ''),
(2411, 7, 5, 68, '', '', '', '', '< Afligido assi. > tlaellelaxitilli. tlatoneualli. tlachichinatztli. tlaatlamachtilli. yolpatzmicqui. tlatlaciauiltilli. moyoltequipachoani. tlachichinacapololli.', ''),
(2412, 7, 5, 69, '', '', '', '', '< Afligidor desta manera. > teellelaxiti. teellelaxitiani. tetoneuani. techichinatzani. ateatlamachtiani. tetlaciauiltiani. techichinacapoloani.', ''),
(2413, 7, 5, 70, '', '', '', '', '< Afligido estar de algun dolor o escozimiento corporal. > nino,tlalteuhnemitia.', ''),
(2414, 7, 5, 71, '', '', '', '', '< Aflicion tal. > netlalteuhnemitiliztli.', ''),
(2415, 7, 5, 72, '', '', '', '', '< Aflicion interior. > yollochichinaquiliztli. yoltone(ne)uiztli.', ''),
(2416, 7, 5, 73, '', '', '', '', '< Afligir a otro assi. > nite,yollochichinatza.', ''),
(2417, 7, 5, 74, '', '', '', '', '< Afligido desta manera. > yolchichinacac.', ''),
(2418, 7, 5, 75, '', '', '', '', '< Afligirse. > ni,yolpatzmiqui. ni,yoltequipachiui. nino,yoltequipachoa.', ''),
(2419, 7, 5, 76, '', '', '', '', '< Afligidos o maltratados de otros. > cocoque. teopouhque. tlatoliniltin.', ''),
(2420, 7, 5, 77, '', '', '', '', '< Afloxar lo que estaua apretado con ataduras. > nitla,caxania. nitla,caxaua.', ''),
(2421, 7, 5, 78, '', '', '', '', '< Afloxarse. > caxani.', ''),
(2422, 7, 5, 79, '', '', '', '', '< Afloxado. > caxanqui. tlacaxanilli.', ''),
(2423, 7, 5, 80, '', '', '', '', '< Afloxamiento. > tlacaxaniliztli.', ''),
(2424, 7, 5, 81, '', '', '', '', '< Afloxarse la enfermedad. > cuetlani. caxaua. yloti.', ''),
(2425, 7, 5, 82, '', '', '', '', '< Afloxada enfermedad. > cuetlanqui. caxauac.', ''),
(2426, 7, 5, 83, '', '', '', '', '< Afloxar emperezando. > ni,cuitlaçotlaua. ni,cuitlatzoltitinemi. ni,cuitlatetzmiliuhtinemi. ni,cuitlananacaiui.', ''),
(2427, 7, 5, 84, '', '', '', '', '< Afloxamiento assi. > cuitlaçotlaualiztli. cuitlatzollotl. cuitlananacayotl.', ''),
(2428, 7, 5, 85, '', '', '', '', '< Aforrar algo. > nitla,ixnepanoa. nitla,quachuia. nitla,ixnamictia nitla,ixtilmayotia.', ''),
(2429, 7, 5, 86, '', '', '', '', '< Aforrada cosa. > tlaixnepanolli. tlaixquachuilli. tlaixtilmayotilli.', ''),
(2430, 7, 5, 87, '', '', '', '', '< Aforrar algo con pellejos. > nitla,euauia. nitla,euaquimiloa.', ''),
(2431, 7, 5, 88, '', '', '', '', '< Aforrada cosa assi. > tlaeuauilli. tlaeuaquimilolli.', ''),
(2432, 7, 5, 89, '', '', '', '', '< Afrechos o saluados. > tlaulxone(n)[u]atl. tlatzetzeliuhcayotl.', ''),
(2433, 7, 5, 90, '', '', '', '', '< Afrentar a otro. > nite,pinauhtia. nite,auilquixtia. nite,pinauia.', ''),
(2434, 7, 5, 91, '', '', '', '', '< Afrenta tal. > tepinauhtiliztli. teauilquixtiliztli. tepinauiliztli.', ''),
(2435, 7, 5, 92, '', '', '', '', '< Afrentadamente assi. > teauilquixtiliztica. tepinauhtiliztica. tepinauiliztica.', ''),
(2436, 7, 5, 93, '', '', '', '', '< Afrentado. > tlapinauhtilli. tlaauilquixtilli. tlapinauilli.', ''),
(2437, 7, 5, 94, '', '', '', '', '< Afrentador tal. > tepinauhtiani. teauilquixtiani. tepinauiani.', ''),
(2438, 7, 5, 95, '', '', '', '', '< Afrentar o enxabonar y baldonar a otro. > nite,(pa)papaca. nite,pacteca. nite,pacçotlaua. nite,atemouia. nite,nouiantoca.', ''),
(2439, 7, 5, 96, '', '', '', '', '< Afrenta tal. > tepapacaliztli. tepactecaliztli. tepacçotlaualiztli. teatemouiliztli. tenouiantocaliztli.', ''),
(2440, 7, 5, 97, '', '', '', '', '< Afrentadamente assi. > tepapacaliztica. tepactecaliztica. tepacçotlaualiztica. teatemouiliztica. tenouiantocaliztica.', ''),
(2441, 7, 5, 98, '', '', '', '', '< Afrentado desta manera y baldonado. > tlapapactli. tlapactectli. tlapacçotlaualli. tlaatemouilli. tla(no)nouiantoctli.', ''),
(2442, 7, 5, 99, '', '', '', '', '< Afrentador tal. > tepapacani. tepactecani. tepacçotlauani. teatemouiani. tenouiantocani.', ''),
(2443, 7, 5, 100, '', '', '', '', '< Afrentar a otro, diziendole sus defectos. > nicte,ixcomaca. nicteixmanilia.', ''),
(2444, 7, 5, 101, '', '', '', '', '< Afrenta tal. > teixcomaquiliztli. teixmaniliztli.', ''),
(2445, 7, 5, 102, '', '', '', '', '< Afrentadamente assi. > teixcomaquiliztica. teixmaniliztica.', ''),
(2446, 7, 5, 103, '', '', '', '', '< Afrentado desta manera. > tlaixcomactli. tlaixmanililli.', ''),
(2447, 7, 5, 104, '', '', '', '', '< Afrentador assi. > quiteixcomacani. quiteixmaniliani.', ''),
(2448, 7, 5, 105, '', '', '', '', '< Agaçaparse. > nite,netlatilia. nino,pachoa.', ''),
(2449, 7, 5, 106, '', '', '', '', '< Agaçapado assi. > mopachoqui. motenetlatilli.', ''),
(2450, 7, 5, 107, '', '', '', '', '< Agallas de arbol. > quauhtotomatl. quauhcapulin.', ''),
(2451, 7, 5, 108, '', '', '', '', '< Agallas de tinta. > nacazcolotl.', ''),
(2452, 7, 5, 109, '', '', '', '', '< Agallas de garganta. > quechtlatlaullotl.', ''),
(2453, 7, 5, 110, '', '', '', '', '< Agonia. > nemociuiliztli. neamanaliztli.', ''),
(2454, 7, 5, 111, '', '', '', '', '< Agonizar. > ye ic nonoc. ye ic nica. ni,natlaça. nino,mociuia.', ''),
(2455, 7, 5, 112, '', '', '', '', '< Agora, tiempo presente. > axca. axcan. {Aduer.}', ''),
(2456, 7, 5, 113, '', '', '', '', '< Agora luego. > niman axca.', ''),
(2457, 7, 5, 114, '', '', '', '', '< Agora es tiempo oportuno y conueniente. > axcampa qualcan.', ''),
(2458, 7, 5, 115, '', '', '', '', '< Agora de aqui avn poco. > oc maya. oc achic. oc cuel achic. oquachic. oquachica. oc ixquich cauitl(i).', ''),
(2459, 7, 5, 116, '', '', '', '', '< Agora poco ha, o denantes. > yeua. quin axca(n). quin izqui y(n). quinica y(n). quin achic.', ''),
(2460, 7, 5, 117, '', '', '', '', '< Agora vn año, o antaño. > ye cexiuitl.', ''),
(2461, 7, 5, 118, '', '', '', '', '< Agorar, tomar agvero. > nino,tetzauia. nite,tetzammati.', ''),
(2462, 7, 5, 119, '', '', '', '', '< Agorear en agua. > atlan, niteitta. atl nic,mana.', ''),
(2463, 7, 5, 120, '', '', '', '', '< Agoreador tal. > atlan teittani. amanani.', ''),
(2464, 7, 5, 121, '', '', '', '', '< Agoreamiento assi. > atlan teittaliztli. amanaliztli.', ''),
(2465, 7, 5, 122, '', '', '', '', '< Agorero que declara algo. > tonalpouhqui.', ''),
(2466, 7, 5, 123, '', '', '', '', '< Agoreria assi. > tonalpoaliztli.', ''),
(2467, 7, 5, 124, '', '', '', '', '< Agostarse algo. > tlauaqui. tlacoçauia. tlachicaua.', ''),
(2468, 7, 5, 125, '', '', '', '', '< Agostada cosa. > (y)[u]acqui. ocoçauiac. ochicauac.', ''),
(2469, 7, 5, 126, '', '', '', '', '< Agosto mes. > yc chicuei metztli yc exiuitl.', ''),
(2470, 7, 5, 127, '', '', '', '', '< Agotar el agua. > n,auatza. nic,uatza yn atl.', ''),
(2471, 7, 5, 128, '', '', '', '', '< Agotada agua. > auatzalli.', ''),
(2472, 7, 5, 129, '', '', '', '', '< Agotador tal. > auatzani. auatzqui.', ''),
(2473, 7, 5, 130, '', '', '', '', '< Agotamiento, o el acto de agotar agua. > auatzaliztli.', ''),
(2474, 7, 5, 131, '', '', '', '', '< Agra cosa. > xococ.', ''),
(2475, 7, 5, 132, '', '', '', '', '< Agro hazerse. > ni,xocoya.', ''),
(2476, 7, 5, 133, '', '', '', '', '< Agro hazer. > nitla,xocolia.', ''),
(2477, 7, 5, 134, '', '', '', '', '< Agrura. > xocoliztli. xococayotl. { Agra }', ''),
(2478, 7, 6, 0, '', '', '$', '', '$FOLIO=6   { A ANTE G. 6 }', ''),
(2479, 7, 6, 1, '', '', '', '', '< Agra fruta. > xocotl.', ''),
(2480, 7, 6, 2, '', '', '', '', '< Agraz o cosa semejante. > xocotetl.', ''),
(2481, 7, 6, 3, '', '', '', '', '< Agra cosa, por madurar. > xoxoctetl, oc xoxouhqui.', ''),
(2482, 7, 6, 4, '', '', '', '', '< Agra sierra o cuesta. > cë[n]can nicac. cencan nicaticac.', ''),
(2483, 7, 6, 5, '', '', '', '', '< Agradarme algo. > nitla,uelitta. nitla,qualitta.', ''),
(2484, 7, 6, 6, '', '', '', '', '< Agradable cosa. > tlauelittalli, tlayequittalli. tlaqualittalli.', ''),
(2485, 7, 6, 7, '', '', '', '', '< Agradamiento. > tlauelittaliztli. tlayequittaliztli. tlaqualittaliztli.', ''),
(2486, 7, 6, 8, '', '', '', '', '< Agradar o complazer a otro. > nite,uellamachtia.', ''),
(2487, 7, 6, 9, '', '', '', '', '< Agradable cosa assi. > teuellamachti.', ''),
(2488, 7, 6, 10, '', '', '', '', '< Agradablemente. > teuellamachtiliztica.', ''),
(2489, 7, 6, 11, '', '', '', '', '< Agradamiento tal. > teuellamachtiliztli.', ''),
(2490, 7, 6, 12, '', '', '', '', '< Agradecer con humildad. > nitla,icnopilmati.', ''),
(2491, 7, 6, 13, '', '', '', '', '< Agradecer a otro alguna cosa. > nite,icnelilmati. nite,tlaçocamati. nite,tlaçomati.', ''),
(2492, 7, 6, 14, '', '', '', '', '< Agradecedor. > teicnelilmatini. tetlaçocamatini. teicnelilmatqui.', ''),
(2493, 7, 6, 15, '', '', '', '', '< Agradecido. > mocnelilmatini. motlaçocamatini. motlaçomatini. motlaçocamati.', ''),
(2494, 7, 6, 16, '', '', '', '', '< Agradecimiento. > necnelilmatiliztli. netlaçocamatiliztli. netlaçomatiliztli.', ''),
(2495, 7, 6, 17, '', '', '', '', '< Agradecido ser. > nino,cnelilmati.', ''),
(2496, 7, 6, 18, '', '', '', '', '< Agrauiar a otro. > nite,tolinia. nite,tequipachoa. çan nen, titetolinia.', ''),
(2497, 7, 6, 19, '', '', '', '', '< Agrauiado. > tlatolinilli. tlatequipacholli. çan nen tlatolinilli.', ''),
(2498, 7, 6, 20, '', '', '', '', '< Agrauiador. > tetoliniani. tetequipachoani. çan nen tetolinia.', ''),
(2499, 7, 6, 21, '', '', '', '', '< Agrauiadamente. > tetoliniliztica. tetequipacholiztica. çan nen tetoliniliztica.', ''),
(2500, 7, 6, 22, '', '', '', '', '< Agrauio. > tetoliniliztli. tetequipacholiztli. çan nen tetoliniliztli.', ''),
(2501, 7, 6, 23, '', '', '', '', '< Agrauiar con demasiada carga. > nite,eticiuitia. nite,etilia.', ''),
(2502, 7, 6, 24, '', '', '', '', '< Agrauiado assi. > tlaeticiuitilli. tlaetililli.', ''),
(2503, 7, 6, 25, '', '', '', '', '< Agrauio tal. > teeticiuiliztli. teetililiztli.', ''),
(2504, 7, 6, 26, '', '', '', '', '< Agua. > atl.', ''),
(2505, 7, 6, 27, '', '', '', '', '< Agua de axi. > chilatl.', ''),
(2506, 7, 6, 28, '', '', '', '', '< Agua de manos. > nematequilatl.', ''),
(2507, 7, 6, 29, '', '', '', '', '< Agua dulce. > yecatl. chipauac atl.', ''),
(2508, 7, 6, 30, '', '', '', '', '< Agua de pozo. > aolhuazatl. atlacomolatl.', ''),
(2509, 7, 6, 31, '', '', '', '', '< Agua bendita. > tlateochiualatl.', ''),
(2510, 7, 6, 32, '', '', '', '', '< Agua cozida. > tlatotonilli atl. ycucic atl.', ''),
(2511, 7, 6, 33, '', '', '', '', '< Agua de pies. > necxipapacatl.', ''),
(2512, 7, 6, 34, '', '', '', '', '< Agua donde se bañan. > nealtilatl.', ''),
(2513, 7, 6, 35, '', '', '', '', '< Agua de baptismo. > nequatequilatl.', ''),
(2514, 7, 6, 36, '', '', '', '', '< Agua de bienauenturança. > tlacnopilhuilizatl.', ''),
(2515, 7, 6, 37, '', '', '', '', '< Agua de testimonio y de verdad. > neltilizatl.', ''),
(2516, 7, 6, 38, '', '', '', '', '< Agua de caño. > apanatl.', ''),
(2517, 7, 6, 39, '', '', '', '', '< Agua biua. > yulilizatl. yuliuani atl.', ''),
(2518, 7, 6, 40, '', '', '', '', '< Agua fria. > ytztic atl. atl cecec.', ''),
(2519, 7, 6, 41, '', '', '', '', '< Agua honda y profunda. > amictlan. auecatlan.', ''),
(2520, 7, 6, 42, '', '', '', '', '< Agua rosada. > xuchatl. xuchiatl.', ''),
(2521, 7, 6, 43, '', '', '', '', '< Agua callentada alfuego. > atotonilli.', ''),
(2522, 7, 6, 44, '', '', '', '', '< Agua callente. > totonqui atl. atl totonqui.', ''),
(2523, 7, 6, 45, '', '', '', '', '< Agua miel. > ayo necutli.', '');
INSERT INTO `test17e` (`id`, `bid`, `fol`, `sno`, `fot`, `fof`, `opm`, `tra`, `pal`, `eng`) VALUES
(2524, 7, 6, 46, '', '', '', '', '< Agua con que lauauan los pedernales, que eran como cuchillos con que sacrificauan y matauä los hombres ante los idolos, la qual agua tenian en lugar de agua bendita, y en mucha veneracion. > ytzpacalatl.', ''),
(2525, 7, 6, 47, '', '', '', '', '< Agua de fuente. > ameyalatl.', ''),
(2526, 7, 6, 48, '', '', '', '', '< Agua de salitre. > tequixquiatl.', ''),
(2527, 7, 6, 49, '', '', '', '', '< Agua pie o vino segundo. > apatzcaluino.', ''),
(2528, 7, 6, 50, '', '', '', '', '< Agua de xaguei. > atecochatl.', ''),
(2529, 7, 6, 51, '', '', '', '', '< Agua que va sosegada y mansa. > yxmantiuh atl.', ''),
(2530, 7, 6, 52, '', '', '', '', '< Agua con que se baño alguno. > nealtilatl.', ''),
(2531, 7, 6, 53, '', '', '', '', '< Aguada cosa, assi como vino, miel o cosa semejante. > ayo. tlaayotilli.', ''),
(2532, 7, 6, 54, '', '', '', '', '< Agua salobre. > poyec atl.', ''),
(2533, 7, 6, 55, '', '', '', '', '< Aguar el vino. > {&c.} nitla,ayotia. nitla,ayutia.', ''),
(2534, 7, 6, 56, '', '', '', '', '< Aguacero. > quiauitl.', ''),
(2535, 7, 6, 57, '', '', '', '', '< Aguacero grande que viene con gran ruido y tempestad. > tlatlatzcatiuitz. yuhquin tlaquequeztiuitz. çoqui[t]tiuitz. yuhquin çoquitl onotiuitz. o tetzauac. o çoquitiac. ehecayo quiauitl.', ''),
(2536, 7, 6, 58, '', '', '', '', '< Aguachil o agua de axi. > chilatl.', ''),
(2537, 7, 6, 59, '', '', '', '', '< Aguadero. busca. açacan. >', ''),
(2538, 7, 6, 60, '', '', '', '', '< Aguado que no beue vino. > atlauanani.', ''),
(2539, 7, 6, 61, '', '', '', '', '< Aguador. busca. açacan. > atlatlacuic.', ''),
(2540, 7, 6, 62, '', '', '', '', '< Aguaducho que viene furioso. > pexontiuh. peyauatiuh. pepeyauatiuh.', ''),
(2541, 7, 6, 63, '', '', '', '', '< Aguamanil. > nematequiliztecomatl. nematequiltecomatl. nematequiloni.', ''),
(2542, 7, 6, 64, '', '', '', '', '< Aguado, que no beue vino. > atlauanani. amo quini octli.', ''),
(2543, 7, 6, 65, '', '', '', '', '< Aguar algo. > nitla,ayotia.', ''),
(2544, 7, 6, 66, '', '', '', '', '< Aguada cosa. > ayo. tlaayotilli.', ''),
(2545, 7, 6, 67, '', '', '', '', '< Aguapie. > yc occan uetzi vino.', ''),
(2546, 7, 6, 68, '', '', '', '', '< Aguardar o esperar a otro con la comida o con otra cosa assi. > nic,chialtia. nic,chielia.', ''),
(2547, 7, 6, 69, '', '', '', '', '< Aguardar al enemigo con esfuerço y animo varonil. > nicno,chieltia.', ''),
(2548, 7, 6, 70, '', '', '', '', '< Aguda cosa y muy afilada. > tene. tenatic. tenitztic.', ''),
(2549, 7, 6, 71, '', '', '', '', '< Agudeza tal. > tenatcayotl. tenitzticayotl.', ''),
(2550, 7, 6, 72, '', '', '', '', '< Agudo de punta. > yacauitztic. yacatzaptic. tzaptic. vitztic. yacauitzauhqui.', ''),
(2551, 7, 6, 73, '', '', '', '', '< Agudeza tal. > yacauitzticayotl. yacatzapticayotl. yacauitzauhcayutl.', ''),
(2552, 7, 6, 74, '', '', '', '', '< Agudo, diligente. > yel. tlacacqui. yciuhcayo. yciuhcayollo.', ''),
(2553, 7, 6, 75, '', '', '', '', '< Agudamente assi, > yellotica. eltiliztica. tlacaccayotica. yciuhcayotica.', ''),
(2554, 7, 6, 76, '', '', '', '', '< Agudeza tal. > yellotl. eltiliztli. tlacaccayotl. iciuhca(ca)yotl.', ''),
(2555, 7, 6, 77, '', '', '', '', '< Agudo de ingenio. > yollo. tlacaquini. yolizma. yolizmatqui. yoliztlama.', ''),
(2556, 7, 6, 78, '', '', '', '', '< Agudamente assi. > yollocayotica. tlacaquiliztica. yolizmatcayotica. yolizmatiliztica.', ''),
(2557, 7, 6, 79, '', '', '', '', '< Aguero. > tetzauitl.', ''),
(2558, 7, 6, 80, '', '', '', '', '< Agujero hecho en madero. > quauhcoyoctli. { Agujero } { A ANTE G ET H. }', ''),
(2559, 7, 6, 81, '', '', '', '', '< Aguiero, o cosa agujerada o horadada. > tlacoyoctli. coyoctic. tlacoyonilli. coyonqui.', ''),
(2560, 7, 6, 82, '', '', '', '', '< Agujerar algo. > nitla,coyonia.', ''),
(2561, 7, 6, 83, '', '', '', '', '< Aguijar a otro. > nite,tototza. nite,iciuitia. nite,tlalochtia.', ''),
(2562, 7, 6, 84, '', '', '', '', '< Aguijada cosa. > tlatototztli. tlatototzalli. tlaiciuitilli.', ''),
(2563, 7, 6, 85, '', '', '', '', '< Aguijador. > tetototzani. teiciuitiani.', ''),
(2564, 7, 6, 86, '', '', '', '', '< Aguijon de hierro o espuela. > tepuztetzopiniloni. tetzopiniloni. tetzapiniloni. tepuztetzatzapitzaloni.', ''),
(2565, 7, 6, 87, '', '', '', '', '< Aguijonear a otro. > nite,tzapinia. nite,tzopinia. nite,ixili', ''),
(2566, 7, 6, 88, '', '', '', '', '< Aguijoneado. > tlatzapinilli. tlaxilli.', ''),
(2567, 7, 6, 89, '', '', '', '', '< Aguijoneador. > tetzapiniani. teixiliani.', ''),
(2568, 7, 6, 90, '', '', '', '', '< Aguijoneamiento. > tetzapiniliztli. teixililiztli.', ''),
(2569, 7, 6, 91, '', '', '', '', '< Aguijon de abeja. > xicotl[i] imiuh. xicotli yteminaya.', ''),
(2570, 7, 6, 92, '', '', '', '', '< Aguila. > quauhtli', ''),
(2571, 7, 6, 93, '', '', '', '', '< Aguilocho. > quauhconetl', ''),
(2572, 7, 6, 94, '', '', '', '', '< Aguila de cabeça bermeja. > cozcaquauhtli.', ''),
(2573, 7, 6, 95, '', '', '', '', '< Aguila negra. > poquauhtli.', ''),
(2574, 7, 6, 96, '', '', '', '', '< Aguila blanca. > yztacquauhtli.', ''),
(2575, 7, 6, 97, '', '', '', '', '< Aguinaldo. > neitlaniliztli yn ipampa yluitl', ''),
(2576, 7, 6, 98, '', '', '', '', '< Aguja para coser. > vitzmallotl. vitzomitl. tlatzomaloni.', ''),
(2577, 7, 6, 99, '', '', '', '', '< Aguja larga para hazer colchones, o para ensartar axi. > chilçoani. chilçoloni.', ''),
(2578, 7, 6, 100, '', '', '', '', '< Agujerear. > nitla,coyonia. nitla,xapotla.', ''),
(2579, 7, 6, 101, '', '', '', '', '< Agujereada cosa. > tlacoyonilli tlaxapotlalli.', ''),
(2580, 7, 6, 102, '', '', '', '', '< Agujero. > coyonqui. tlacoyoctli. coyoctic. xapochtic', ''),
(2581, 7, 6, 103, '', '', '', '', '< Agujero, donde se guardä las agujas. > vitzmallocallotl. vitzmallocomitl.', ''),
(2582, 7, 6, 104, '', '', '', '', '< Aguzar punta o ser el primero o delantero de los que caminan, o de los que estan puestos en orden. > nitla,yacauitzoa nitla,yacachiqui. nitla,yacatia.', ''),
(2583, 7, 6, 105, '', '', '', '', '< Aguzada punta. > tlayacauitzolli tlayacachictli.', ''),
(2584, 7, 6, 106, '', '', '', '', '< Aguzarse assi. > yacauitzaui.', ''),
(2585, 7, 6, 107, '', '', '', '', '< Aguzar, dar filo. busca afilar. >', ''),
(2586, 7, 6, 108, '', '', '', '', '< Aguzadera piedra. > tlatentiloni.', ''),
(2587, 7, 6, 109, '', '', '', '', '< Aguzador. > tlatentiani. tlatenti.', ''),
(2588, 7, 6, 110, '', '', '', '', '< Ahao, ola, oyes. > xi. nica. niltze. nopiltze. taui. netle. ayo. yeccue.', ''),
(2589, 7, 6, 111, '', '', '', '', '< Ahechar o limpiar algo. > nitla,yectia.', ''),
(2590, 7, 6, 112, '', '', '', '', '< Ahechador. > tlayectiani.', ''),
(2591, 7, 6, 113, '', '', '', '', '< Ahechada cosa. > tlayectilli.', ''),
(2592, 7, 6, 114, '', '', '', '', '< Ahechadura. > tlayectiliztli.', ''),
(2593, 7, 6, 115, '', '', '', '', '< Ahermosear o hermosear algo. > nitla,qualnextia. nitla,qualtilia. nitla,chipaua.', ''),
(2594, 7, 6, 116, '', '', '', '', '< Ahincar importunando. > nitetla,matataquilia. nite,tequiuia. < Et per metaphoram. > teixtlan nipilcatinemi. a ninonauatilma. a ninopeuilma.', ''),
(2595, 7, 6, 117, '', '', '', '', '< Ahincadamente assi. > tetlamatataquiliztica. tetequiuiliztica. teixtlan pilcatinemiliztica.', ''),
(2596, 7, 6, 118, '', '', '', '', '< Ahinco. > tetlamatataquiliztli. tetequiuiliztli. teixtlä pilcatinemiliztli.', ''),
(2597, 7, 6, 119, '', '', '', '', '< Ahitarme. > nino,xuitia. ni,nelixuitia. ni,nelincoa.', ''),
(2598, 7, 6, 120, '', '', '', '', '< Ahito o el que esta ahito. > moxuitiqui. melixuitiqui melinco.', ''),
(2599, 7, 6, 121, '', '', '', '', '< Ahito. s. el acto de estar ahito. > nexuitiliztli. neelixuitiliztli.', ''),
(2600, 7, 6, 122, '', '', '', '', '< Ahitar a otro. > nite,ixuitia. nite,elixuitia.', ''),
(2601, 7, 6, 123, '', '', '', '', '< Ahocinar se el rio. > mo,teuilacachoa. m,axicyotia. mo,malacachoa. çoloni.', ''),
(2602, 7, 6, 124, '', '', '', '', '< Ahogar cö las manos a otro. > nite,quechmatiloa. nite,quechmateloa.', ''),
(2603, 7, 6, 125, '', '', '', '', '< Ahogado assi. > tlaquechmatelolli. tlaquechmatilolli.', ''),
(2604, 7, 6, 126, '', '', '', '', '< Ahogador tal. > tequechmateloani. teq~chmatiloani.', ''),
(2605, 7, 6, 127, '', '', '', '', '< Ahogamiento tal. > tequechmateloliztli. tequechmatiloliztli.', ''),
(2606, 7, 6, 128, '', '', '', '', '< Ahogar cö soga. > nite,que[c]hmecania.', ''),
(2607, 7, 6, 129, '', '', '', '', '< Ahogado assi. > tlaquechmecanilli.', ''),
(2608, 7, 6, 130, '', '', '', '', '< Ahogador tal. > tequechmecaniani.', ''),
(2609, 7, 6, 131, '', '', '', '', '< Ahogamiento assi. > tequechmecaniliztli.', ''),
(2610, 7, 6, 132, '', '', '', '', '< Ahogar le a otro su hijo cö las manos. > nicte,quechmatelhuia. nicte,quechmatilhuia.', ''),
(2611, 7, 6, 133, '', '', '', '', '< Ahogar me en agua que corre. > n,atoco. nin,atoyauia.', ''),
(2612, 7, 6, 134, '', '', '', '', '< Ahogado assi. > atococ. matoyaui. tlaatoctilli.', ''),
(2613, 7, 6, 135, '', '', '', '', '< Ahogador tal. > teatoctiani. tlatoyauiani. teatoyauiani.', ''),
(2614, 7, 6, 136, '', '', '', '', '< Ahogamiento assi. > atocoliztli. neatoyauiliztli.', ''),
(2615, 7, 6, 137, '', '', '', '', '< Ahogarme en la mar o en agua represada. > n,atlam mi(c)qui.', ''),
(2616, 7, 6, 138, '', '', '', '', '< Ahogado assi. > atlam micqui.', ''),
(2617, 7, 6, 139, '', '', '', '', '< Ahogamiento tal. > atlam miquiliztli.', ''),
(2618, 7, 6, 140, '', '', '', '', '< Ahogarse con algun bocado que se atraueso. > nin,elcima. nin,ihiotzaqua.', ''),
(2619, 7, 6, 141, '', '', '', '', '< Ahogado assi. > melcinqui. mihiotzacqui.', ''),
(2620, 7, 6, 142, '', '', '', '', '< Ahogamiëto tal. > neelcimaliztli. neihiotzaqualiztli.', ''),
(2621, 7, 6, 143, '', '', '', '', '< Ahoyar o hazer hoyo. > nitla,coyonia. nitla,comoloa.', ''),
(2622, 7, 6, 144, '', '', '', '', '< Ahorcarse. > nino,mecania. nino,piloa.', ''),
(2623, 7, 6, 145, '', '', '', '', '< Ahorcado. > tlamecanilli. tlapilolli. momecani.', ''),
(2624, 7, 6, 146, '', '', '', '', '< Ahorcador. > tepiloani. temecaniani.', ''),
(2625, 7, 6, 147, '', '', '', '', '< Ahorcamiento. > temecaniliztli. tepiloliztli. nemecaniliztli. nepiloliztli.', ''),
(2626, 7, 6, 148, '', '', '', '', '< Ahorcar a otro. > nite,mecania. nite,piloa.', ''),
(2627, 7, 6, 149, '', '', '', '', '< Ahorrar. > nitla,tlacoitta. < s gastar moderadamente. >', ''),
(2628, 7, 6, 150, '', '', '', '', '< Ahorrada cosa assi. > tlatlacoittalli.', ''),
(2629, 7, 6, 151, '', '', '', '', '< Ahorrar esclauo. > nic.tlatlacollaça.', ''),
(2630, 7, 6, 152, '', '', '', '', '< Ahorrado assi. > tlatlatlacollaçalli. tlatlatlacollaztli.', ''),
(2631, 7, 6, 153, '', '', '', '', '< Ahuyentar o hazer huir a otro. > nite,chololtia. nite,yeltia.', ''),
(2632, 7, 6, 154, '', '', '', '', '< Ahuyentada cosa. > tlachololtilli. tlayeltilli.', ''),
(2633, 7, 6, 155, '', '', '', '', '< Ahuyentador. > techololt[i]ani. teyeltiani.', ''),
(2634, 7, 6, 156, '', '', '', '', '< Ahuyentamiento. > techololtiliztli teyeltiliztli.', ''),
(2635, 7, 6, 157, '', '', '', '', '< Ahuyentar o esparzir ganado o gente. > nite,cemmana. nite,cecemmana. nite,moyaua. nite,momoyaua. { Ahuye }', ''),
(2636, 7, 7, 0, '', '', '$', '', '$FOLIO=7   { A ANTE H, E T, Y. 7 }', ''),
(2637, 7, 7, 1, '', '', '', '', '< Ahuyentada cosa assi. > tlacemmätli. tlamomoyauhtli.', ''),
(2638, 7, 7, 2, '', '', '', '', '< Ahuyentador tal. > tecemmanani. temomoyauani.', ''),
(2639, 7, 7, 3, '', '', '', '', '< Ahuyentamiento desta manera. > tecemmanaliztli. temoyaualiztli. temomoyaualiztli.', ''),
(2640, 7, 7, 4, '', '', '', '', '< Ahumar algo, assi como pared o manta > {&c.} nitla,pocheua. nitla,pochectilia.', ''),
(2641, 7, 7, 5, '', '', '', '', '< Ahumar se desta manera. > ni,pocheua. ni,pochectia.', ''),
(2642, 7, 7, 6, '', '', '', '', '< Ahumada cosa assi. > pucheuac. puchectic. tlapucheualli.', ''),
(2643, 7, 7, 7, '', '', '', '', '< Ahurtadillas. > çan ychtaca.', ''),
(2644, 7, 7, 8, '', '', '', '', '< Ahusar algo. > nitla,yacapitzaua. nitlayacauitzoa.', ''),
(2645, 7, 7, 9, '', '', '', '', '< Ahusada cosa. > yacapitzauac. yacapitzactic. yacauitztic.', ''),
(2646, 7, 7, 10, '', '', '', '', '< Ahusador. > tlayacapitzauani. tlayacauitzoani.', ''),
(2647, 7, 7, 11, '', '', '', '', '< Ahusadura. > tlayacapitzaualiztli. tlayacauitzoliztli', ''),
(2648, 7, 7, 12, '', '', '', '', '< Ay donde tu estas. > oncano[n].', ''),
(2649, 7, 7, 13, '', '', '', '', '< Ay ay ay. quexandose. > ax ax. aqua. elele', ''),
(2650, 7, 7, 14, '', '', '', '', '< Ayer. > yalhua.', ''),
(2651, 7, 7, 15, '', '', '', '', '< Ayna. busca presto. >', ''),
(2652, 7, 7, 16, '', '', '', '', '< Ayo oaya. > teuapauani. tlacazcalti. tlacazcaltiani. teixtlamachti.', ''),
(2653, 7, 7, 17, '', '', '', '', '< Ayrar a otro. > nite,qualania. nite,tlauelcuitia. nite,neçumaltia. nite,tlauelpoçonaltia.', ''),
(2654, 7, 7, 18, '', '', '', '', '< Ayrado. > qualanqui. qualanini. tlauelcuic. moçomani. tlauelpoçonini. tlauelpoçonqui. tlauele.', ''),
(2655, 7, 7, 19, '', '', '', '', '< Ayradamente, o con yra. > qualancayotica. tlauellotica. neçumaliztica. tlauelpoçoniliztica. tlauelcacopa.', ''),
(2656, 7, 7, 20, '', '', '', '', '< Ayrado largo tiempo. > qualancanemi. yqualä ypan nemi. yqualan ypan nemini.', ''),
(2657, 7, 7, 21, '', '', '', '', '< Ayre. > ehecatl.', ''),
(2658, 7, 7, 22, '', '', '', '', '< Ayre delgado. > ecapitzactli. ecaxoctli. ehecapeyactli', ''),
(2659, 7, 7, 23, '', '', '', '', '< Ayslarse. > nin,atzaqua', ''),
(2660, 7, 7, 24, '', '', '', '', '< Ayslado. > matzacqui.', ''),
(2661, 7, 7, 25, '', '', '', '', '< Ayuda echar o melezina. > nitetzimpamaca. nitepamaca. tecuitlapampa nitepamaca. tetlampa nictemaca yn patli.', ''),
(2662, 7, 7, 26, '', '', '', '', '< Ayuda dar o melezina de otra manera. > nite,tzinana.', ''),
(2663, 7, 7, 27, '', '', '', '', '< Ayuda o xeringa. > tepamaconi. tetzimpamaconi.', ''),
(2664, 7, 7, 28, '', '', '', '', '< Ayudar a otro. > nite,paleuia. tepan ninilacatzoa. nite,matlapaliuhcatilia. tepä ninomana. nite,nanamiqui.', ''),
(2665, 7, 7, 29, '', '', '', '', '< Ayuda assi. > tepaleuiliztli. tepan neylacatzoliztli. tematlapaliuhcatililiztli. tepan nemanaliztli. tenanamiquiliztli.', ''),
(2666, 7, 7, 30, '', '', '', '', '< Ayudado assi. > tlapaleuilli. {&c.}', ''),
(2667, 7, 7, 31, '', '', '', '', '< Ayudador tal. > tepaleuiani. tepam milacatzoani. tepan momanani.', ''),
(2668, 7, 7, 32, '', '', '', '', '< Ayuda desta manera, > tepaleuiliztli. {&c.}', ''),
(2669, 7, 7, 33, '', '', '', '', '< Ayudar a missa, a cantar o a trabajar. > nite,nanquilia.', ''),
(2670, 7, 7, 34, '', '', '', '', '< Ayuda assi. > tenanquililiztli.', ''),
(2671, 7, 7, 35, '', '', '', '', '< Ayudado desta manera. > tlananquililli.', ''),
(2672, 7, 7, 36, '', '', '', '', '< Ayudador assi. > tlananquiliani tlananquiliqui. tenäquiliani. tenanquiliqui.', ''),
(2673, 7, 7, 37, '', '', '', '', '< Ayudar a pagar el tributo. > nite,tequinanamiqui.', ''),
(2674, 7, 7, 38, '', '', '', '', '< Ayudador tal. > tetequinanamiquini.', ''),
(2675, 7, 7, 39, '', '', '', '', '< Ayuda assi. > tetequinanamiquiliztli.', ''),
(2676, 7, 7, 40, '', '', '', '', '< Ayudar a lleuar la carga a otro paraque descanse vn rato. > nite,ceuia.', ''),
(2677, 7, 7, 41, '', '', '', '', '< Ayudador tal. > teceuiani.', ''),
(2678, 7, 7, 42, '', '', '', '', '< Ayudar con gente armada. > nite,oquichtilia. yaoc nitepaleuia.', ''),
(2679, 7, 7, 43, '', '', '', '', '< Ayudador assi. > teoquichtiliani. yaoc tepaleuiani.', ''),
(2680, 7, 7, 44, '', '', '', '', '< Ayuda tal. > teoquichtililiztli. yaoc tepaleuiliztli.', ''),
(2681, 7, 7, 45, '', '', '', '', '< Ayudar porque me ayuden. > nite,macoa. nite,macoua.', ''),
(2682, 7, 7, 46, '', '', '', '', '< Ayuda tal. > temacoualiztli. temacoaliztli.', ''),
(2683, 7, 7, 47, '', '', '', '', '< Ayudado assi. > tlamacoalli. tlamacoualli. tlamacouhqui.', ''),
(2684, 7, 7, 48, '', '', '', '', '< Ayudador tal. > temacoani. temacouani. temacouhqui.', ''),
(2685, 7, 7, 49, '', '', '', '', '< Ayudar a otro haziendose de su vando. > teuic ninoquetza. tetloc ninoquetza. teuicpa neua.', ''),
(2686, 7, 7, 50, '', '', '', '', '< Ayuda assi. > teuic nequetzaliztli. tetloc nequetzaliztli. teuic eualiztli.', ''),
(2687, 7, 7, 51, '', '', '', '', '< Ayudador tal. > teuic moquetzani. tetloc moquetzani. teuicpa euani.', ''),
(2688, 7, 7, 52, '', '', '', '', '< Ayunar. > nino,çaua. ni,tlaqualizcaua. ni,tlacatlaqua.', ''),
(2689, 7, 7, 53, '', '', '', '', '< Ayunador. > moçauani. tlaqualizcauani. tlacatlaquani.', ''),
(2690, 7, 7, 54, '', '', '', '', '< Ayuno. > neçaualiztlï. tlaqualizcaualiztli. tlacatlaqualiztli.', ''),
(2691, 7, 7, 55, '', '', '', '', '< Ayuno, el que no seha desayunado. > ayatle quiqua.', ''),
(2692, 7, 7, 56, '', '', '', '', '< Ayuntar algo. > nitla,nechicoa. nitla,centlalia. nitla,ololoa. nitla,tecpichoa. nitla,tepeuhtitlalia.', ''),
(2693, 7, 7, 57, '', '', '', '', '< Ayuntada cosa. > tlanechicolli. tlacentlalilli. tlaolololli. tlatecpicholli. tlatepeuhtitlalilli.', ''),
(2694, 7, 7, 58, '', '', '', '', '< Ayuntamiento tal. > tlanechicoliztli. tlacentlaliliztli tlaolololiztli. tlatecpicholiztli. tlatepeuhtitlaliliz[t]li.', ''),
(2695, 7, 7, 59, '', '', '', '', '< Ayuntar y recoger los peccados, trayendo los a la memoria para los confessar. > nino,tlacentlalilia. nino,tlatlania. nino,tlatemolia. niquicxitoca yn notlatlacol. nic,teputztoca yn notlatlacol.', ''),
(2696, 7, 7, 60, '', '', '', '', '< Ayuntar en vno mayz, cacao o otras cosas assi. > nitla,centema.', ''),
(2697, 7, 7, 61, '', '', '', '', '< Ayuntada cosa assi. > tlacentemalli.', ''),
(2698, 7, 7, 62, '', '', '', '', '< Ayuntamiento tal. > tlacentemaliztli.', ''),
(2699, 7, 7, 63, '', '', '', '', '< Ayuntar en vno, o hazer que dos cosas sean vna. > nite,cetilia. nitla,cetilia.', ''),
(2700, 7, 7, 64, '', '', '', '', '< Ayuntadas assi. > tlacetililtin.', ''),
(2701, 7, 7, 65, '', '', '', '', '< Ayuntamiento tal. > tecetililiztli. tlacetililiztli.', ''),
(2702, 7, 7, 66, '', '', '', '', '< Ayuntador desta manera. > tecetiliani. tlacëtetiliani.', ''),
(2703, 7, 7, 67, '', '', '', '', '< Ayuntar en alguna cancion todos los loores de hazañas que alguno hizo. > nic,centeca. nic,cecepanoa. nic,cecentlalia yn iyecteneualoca.', ''),
(2704, 7, 7, 68, '', '', '', '', '< Ayuntarse carnalmente el varon con la muger. > tetech naci. nite,nepanoa. nite,teca. nite,cuicui. { Ayunta } { A ANTE Y, ET L. }', ''),
(2705, 7, 7, 69, '', '', '', '', '< Ayuntamiento assi. > tetech axiliztli. nenepanoliztli.', ''),
(2706, 7, 7, 70, '', '', '', '', '< Ayuntar o allegar vna cosa a otra. > nitla,netechpachoa.', ''),
(2707, 7, 7, 71, '', '', '', '', '< Ayuntada cosa assi. > tlanetechpacholli.', ''),
(2708, 7, 7, 72, '', '', '', '', '< Ayuntador tal. > tlanetechpachoani.', ''),
(2709, 7, 7, 73, '', '', '', '', '< Ayuntamiento assi. > tlanetechpacholiztli.', ''),
(2710, 7, 7, 74, '', '', '', '', '< Ayuntar o juntar consigo la madre a su hijo apretandolo con los braços. > notech nic,pachoa. notech nic,papachoa.', ''),
(2711, 7, 7, 75, '', '', '', '', '< Ayuntar o juntar mantas vnas con otras cosiendolas. > nitla,netechtlalia. nitla,neteçaloa.', ''),
(2712, 7, 7, 76, '', '', '', '', '< Ayuntadas mantas assi. > tlanetechtlalilli. tlaneteçalolli.', ''),
(2713, 7, 7, 77, '', '', '', '', '< Ayuntador tal. > tlanetechtlaliani. tlaneteçaloani.', ''),
(2714, 7, 7, 78, '', '', '', '', '< Ayuntamiento tal. > tlanetechtlaliliztli. tlaneteçaloliztli.', ''),
(2715, 7, 7, 79, '', '', '', '', '< Ayuntarse la gente. > mo,teca. mo,tecpichoa. tecpichaui. cenquiça. cenquixoa. mocentlalia. monechicoa.', ''),
(2716, 7, 7, 80, '', '', '', '', '< Ayuntamiento assi. > netequiliztli. netecpicholiztli. netecpichauiliztli. cenquiçaliztli. cenquixoaliztli. necentlaliliztli. nenechicoliztli.', ''),
(2717, 7, 7, 81, '', '', '', '', '< Ayuntarse los rios. > monepanoa yn atl. cetia yn atl.', ''),
(2718, 7, 7, 82, '', '', '', '', '< Ayuntamiëto de rios o de aguas. > anepanolli.', ''),
(2719, 7, 7, 83, '', '', '', '', '< Ayuntamiento de naciones. > tlacanechicolli. tlacanechicoltin. coatlaca. nepapan tlatlaca.', ''),
(2720, 7, 7, 84, '', '', '', '', '< Ajena cosa. > teaxca. tetlatqui. teyuca. tecococauh. teyocauh.', ''),
(2721, 7, 7, 85, '', '', '', '', '< Ajeno ser. > nite,axca. nite,tlatqui. nite,yuca. nite,yocauh. nite,cococauh.', ''),
(2722, 7, 7, 86, '', '', '', '', '< Aio. lo mismo. > vel. castillan xonacatl.', ''),
(2723, 7, 7, 87, '', '', '', '', '< Aizquierdas hazer algo. > nitla,opochuia. nitla,opochchiua.', ''),
(2724, 7, 7, 88, '', '', '', '', '< Aizquierdas hecho. > tlaopochuilli. tlaopo[ch]chiuhtli.', ''),
(2725, 7, 7, 89, '', '', '', '', '< ALa para bolar. > aaztli. atlapalli. aztlacapalli. amatlapalli.', ''),
(2726, 7, 7, 90, '', '', '', '', '< Ala pequeña. > aaztontli. atlapaltontli. aztlacapaltontli. amatlapaltontli.', ''),
(2727, 7, 7, 91, '', '', '', '', '< Ala de papel. > ama(a)tlapalli. amaaaztli. {&c.}', ''),
(2728, 7, 7, 92, '', '', '', '', '< Ala de tejado. > anayotl. atenamitl.', ''),
(2729, 7, 7, 93, '', '', '', '', '< Alabar a otro. > nite,yecteneua. nite,yequitoa. nite,qualitoa.', ''),
(2730, 7, 7, 94, '', '', '', '', '< Alabança. > teyecteneualiztli. tequalitoliztli.', ''),
(2731, 7, 7, 95, '', '', '', '', '< Alabarse. > nino,yecteneua. nino,qualitoa. nino,yequitoa.', ''),
(2732, 7, 7, 96, '', '', '', '', '< Alabado de otros. > tlayecteneualli. tlayequitolli. tlaqualitolli. tlayecteneuhtli.', ''),
(2733, 7, 7, 97, '', '', '', '', '< Alabarse con mentira auer hecho de algo. > nicno,chiualyetoca. nicno,chiualtoca.', ''),
(2734, 7, 7, 98, '', '', '', '', '< Alabança assi. > nechiualtoquiliztli.', ''),
(2735, 7, 7, 99, '', '', '', '', '< Alabarse con jactancia y presumpcion. > nino,chachamaua. nino,cicinoa. nino,tlanitztia. nino,tlatlanitztia. nino,yecteneua. nino,qualitoa.', ''),
(2736, 7, 7, 100, '', '', '', '', '< Alabança tal. > nechachamaualiztli. necicinoliztli. netlanitztiliztli. {&c.}', ''),
(2737, 7, 7, 101, '', '', '', '', '< Alabado desta manera. i. el que asi mismo alaba. > chamatl. mochachamauani. mocicinoani. motlanitztiani.', ''),
(2738, 7, 7, 102, '', '', '', '', '< Alabastro, o cosa semejante. > azcalli. tezcaltetl.', ''),
(2739, 7, 7, 103, '', '', '', '', '< Ala mano derecha. > nomayeccampa. nomayauhcampa.', ''),
(2740, 7, 7, 104, '', '', '', '', '< Alambre o cobre. > tepuztli.', ''),
(2741, 7, 7, 105, '', '', '', '', '< Alamo o arbol semejante a el. > pepeyolquauitl.', ''),
(2742, 7, 7, 106, '', '', '', '', '< Alançar de si algo. > nitla,topeua. nitla,ixicquetza.', ''),
(2743, 7, 7, 107, '', '', '', '', '< Alançada cosa. > tlatopeuhtli. tlaixicquetzalli.', ''),
(2744, 7, 7, 108, '', '', '', '', '< Alancear. > nite,ixili. nite,tepuztopilhuia.', ''),
(2745, 7, 7, 109, '', '', '', '', '< Alanceado. > tlaxilli. tlatepuztopilhuilli.', ''),
(2746, 7, 7, 110, '', '', '', '', '< Alanceador. > teixilini. teixilqui. tetepuztopilhuiani.', ''),
(2747, 7, 7, 111, '', '', '', '', '< Alanceamiento. > teixililiztli. tetepuztopilhuiliztli.', ''),
(2748, 7, 7, 112, '', '', '', '', '< Ala oreja. > tenacaztlan. ynacaztlan.', ''),
(2749, 7, 7, 113, '', '', '', '', '< Ala postre. > çatepan. quintepan. tlatzacca[n]. ça tlatzacca[n]. ça tlatzonco.', ''),
(2750, 7, 7, 114, '', '', '', '', '< Alarde hazer. > nitla,tlauiznextia.', ''),
(2751, 7, 7, 115, '', '', '', '', '< Alarde. > tlauiznextiliztli.', ''),
(2752, 7, 7, 116, '', '', '', '', '< Alargar algo. > nitla,ueyaquilia. nitla,ueilia.', ''),
(2753, 7, 7, 117, '', '', '', '', '< Alargada cosa. > tlaueyaquililli.', ''),
(2754, 7, 7, 118, '', '', '', '', '< Alargar o dilatar tiempo. > nitla,uecatlaça. nitla,uecaua. nic,uecatlaztiuh.', ''),
(2755, 7, 7, 119, '', '', '', '', '< Alaridos dar en la guerra. > nino,tenuitequi. nino,tëpapauia.', ''),
(2756, 7, 7, 120, '', '', '', '', '< Alarido tal. > netenuitequiliztli. netempapauiliztli. tlaxaxauaniliztli. tlacacauaca. tlaxaxauani.', ''),
(2757, 7, 7, 121, '', '', '', '', '< Alaridos o aullidos dar. > nite,coyoua. ni,chichiquilitzatzi.', ''),
(2758, 7, 7, 122, '', '', '', '', '< Alarido tal. > tecoyoualiztli. chichiquilitzatziliztli.', ''),
(2759, 7, 7, 123, '', '', '', '', '< Ala sazon. > vel iquac.', ''),
(2760, 7, 7, 124, '', '', '', '', '< Ala rayz del arbol. > ynelhuayocan.', ''),
(2761, 7, 7, 125, '', '', '', '', '< Albacea. > ytech necaualotiuh. ytech nenauatilotiuh nanauatilotiuh.', ''),
(2762, 7, 7, 126, '', '', '', '', '< Albañi. > tlahquilqui.', ''),
(2763, 7, 7, 127, '', '', '', '', '< Albarda. > pepechtli.', ''),
(2764, 7, 7, 128, '', '', '', '', '< Albeitar. > cauallopati. cauallopatiani.', ''),
(2765, 7, 7, 129, '', '', '', '', '< Albeiteria. > cauallopatiliztli.', ''),
(2766, 7, 7, 130, '', '', '', '', '< Alberca. > tlaquilacaxitl.', ''),
(2767, 7, 7, 131, '', '', '', '', '< Alborear. busca amanecer. >', ''),
(2768, 7, 7, 132, '', '', '', '', '< Alborotar gente. > nite,comonia. nite,acomana. nite,tlaltecuinaltia.', ''),
(2769, 7, 7, 133, '', '', '', '', '< Alborotarse la gente. > necomonilo. neacomanalo. tlaltecuini.', ''),
(2770, 7, 7, 134, '', '', '', '', '< Alborotada gente. > tlacomonilli. tlaacomanalli.', ''),
(2771, 7, 7, 135, '', '', '', '', '< Alborotador. > tecomoniani. teacomanani. tetlaltecuinaltiani.', ''),
(2772, 7, 7, 136, '', '', '', '', '< Alboroto. > necomoniliztli. neacomanaliztli. tetlaltecuiniliztli. tlaltecuinaliztli.', ''),
(2773, 7, 7, 137, '', '', '', '', '< Alborotarse alguno y desasossegarse. > nino,yolacomana. nino,tlapololtia. nino,mociuia.', ''),
(2774, 7, 7, 138, '', '', '', '', '< Alcabo o al fin. busca a la postre. > { Alcacer }', ''),
(2775, 7, 8, 0, '', '', '$', '', '$FOLIO=8   { A ANTE L. 8 }', ''),
(2776, 7, 8, 1, '', '', '', '', '< Alcacer. > toquizhuatl.', ''),
(2777, 7, 8, 2, '', '', '', '', '< Alcaduz. > apipilolli.', ''),
(2778, 7, 8, 3, '', '', '', '', '< Alcahuetear. > nite,tlanochilia nite,tlanaualnochilia. nite,tlanauatilia. nite,tzinnamaca.', ''),
(2779, 7, 8, 4, '', '', '', '', '< Alcahuete. > tetlanochili. tetlanaualnochili. tetlanochiliani. tetlanaualnochiliani. tetlanauatiliani. tetlanochiliqui. tetlanaualnochiliqui. tetlanauatiliqui.', ''),
(2780, 7, 8, 5, '', '', '', '', '< Alcahueteria. > tetlanochililiztli. tetlanaualnochiliztli. tetlanauatiliztli.', ''),
(2781, 7, 8, 6, '', '', '', '', '< Alcaide de carcel. > teilpilcallapixqui.', ''),
(2782, 7, 8, 7, '', '', '', '', '< Alcaide de fortaleza. > yaocallapixqui.', ''),
(2783, 7, 8, 8, '', '', '', '', '< Alcalde. lo mismo. >', ''),
(2784, 7, 8, 9, '', '', '', '', '< Alcaldia. > alcaldeyotl.', ''),
(2785, 7, 8, 10, '', '', '', '', '< Alcançar al que camina, o al que huye. > nite,aci. nöte,aci.', ''),
(2786, 7, 8, 11, '', '', '', '', '< Alcance assi. > teaxiliztli.', ''),
(2787, 7, 8, 12, '', '', '', '', '< Alcançar o llegar alo que esta en alto. > n,aci. non,aci.', ''),
(2788, 7, 8, 13, '', '', '', '', '< Alcançar a saber algo de rayz y enteramente, o tener mucha familiaridad con algunos señores. > n,aaci.', ''),
(2789, 7, 8, 14, '', '', '', '', '< Alcançar o tomar lo que esta en alto, assi como plato, ropa o cosas manuales. > nic,ana. nocon,ana.', ''),
(2790, 7, 8, 15, '', '', '', '', '< Alcançar lo desseado. > nitla,cnopilhuia. no,maceualti. nicnopilti.', ''),
(2791, 7, 8, 16, '', '', '', '', '< Alcançar en cuenta a otro. > nic,pantlaxilia. nic,yolmaxiltia.', ''),
(2792, 7, 8, 17, '', '', '', '', '< Alcance en cuenta. > tlapantlaçaliztli.', ''),
(2793, 7, 8, 18, '', '', '', '', '< Alcançar de cuenta a otro, entendiendole. > a iuh niteitta. auh nitecaqui. nite,yolloitta. nite,yollomati. nite,iztlacoa.', ''),
(2794, 7, 8, 19, '', '', '', '', '< Alcançado assi de cuenta. > a yuh tlattalli. a yuh ittoni. a yuh caconi.', ''),
(2795, 7, 8, 20, '', '', '', '', '< Alcance de cuenta. > a iuh teittaliztli. a iuh tecaquiliztli.', ''),
(2796, 7, 8, 21, '', '', '', '', '< Alcarchofa. > vitzquiltzontecomatl. vitzquilitl itzötecon.', ''),
(2797, 7, 8, 22, '', '', '', '', '< Alcauala. > tianquiztequitl. puchteca tequitl.', ''),
(2798, 7, 8, 23, '', '', '', '', '< Alcaualero. > tianquiztequitqui. pu(e)[c]htecatequitqui.', ''),
(2799, 7, 8, 24, '', '', '', '', '< Alçar algo. > nitla,acocui. nitla,acoquixtia.', ''),
(2800, 7, 8, 25, '', '', '', '', '< Alçarse en alto el agua o la culebra. > nino,tompitzquetza. nino,tompitzqueua. nino,to[n]uitzoa. nino,tlamina.', ''),
