(2812, 7, 8, 37, '', '', '', '', '< Aldeano. > (n)[m]illa tlacatl. millacatl.', ''),
(2813, 7, 8, 38, '', '', '', '', '< Alderredor. > tlayaualiuhca[n].', ''),
