(2824, 7, 8, 49, '', '', '', '', '< Alegremente assi. > neellelquixtiliztica. necemeltiliztica. nececeltiliztica.', ''),
(2825, 7, 8, 50, '', '', '', '', '< Alegrarme del mal de otro. > teca nauia. teca nipaqui teca n,ahauia. teca nipapaqui.', ''),
(2826, 7, 8, 51, '', '', '', '', '< Alegre assi. > teca paquini. teca papaquini. teca ahauiani. teca auiani.', ''),
