(2834, 7, 8, 59, '', '', '', '', '< Alferez. > yaoc quachpanitquic.', ''),
(2835, 7, 8, 60, '', '', '', '', '< Alfiler. > tepuztlatlatzicoltiloni. tilmaçoani.', ''),
(2836, 7, 8, 61, '', '', '', '', '< Alforia. > xiquipilli.', ''),
(2837, 7, 8, 62, '', '', '', '', '< Algiue o cisterna. > atlalilli. atatactli.', ''),
(2838, 7, 8, 63, '', '', '', '', '< Algo. > ytla.', ''),
(2839, 7, 8, 64, '', '', '', '', '< Algodon. > ychcatl.', ''),
(2840, 7, 8, 65, '', '', '', '', '< Alguna cosa. > ytla.', ''),
