(2848, 7, 8, 73, '', '', '', '', '< Alguno o alguna. > aca.', ''),
(2849, 7, 8, 74, '', '', '', '', '< Algunos o algunas. > acame.', ''),
(2850, 7, 8, 75, '', '', '', '', '< Algunos pocos. > çan quezquin. ça quezquintin.', ''),
(2851, 7, 8, 76, '', '', '', '', '< Alhajas > chantlatquitl. chanyeloani.', ''),
(2852, 7, 8, 77, '', '', '', '', '< Alholi o troxa de trigo o maiz. > cuezcomatl.', ''),
(2853, 7, 8, 78, '', '', '', '', '< Alhombra. > tilmaicxipepechtli. tilmapepechtli.', ''),
