(2970, 7, 9, 38, '', '', '', '', '< Aluanega de red. > quamatlatl.', ''),
(2971, 7, 9, 39, '', '', '', '', '< Aluanega ponerse. > nino,quamatlatia.', ''),
(2972, 7, 9, 40, '', '', '', '', '< Albañi. > tlaquilqui.', ''),
