(3751, 7, 14, 35, '', '', '', '', '< Arrepentirse de lo que pretendia hazer, mudando el parecer. > nino,yolcuepa. nino,tzinquixtia.', ''),
(3752, 7, 14, 36, '', '', '', '', '< Arrepentido assi. > moyolcuepqui. motzinquixtiqui.', ''),
(3753, 7, 14, 37, '', '', '', '', '< Arrepentimiento tal. > neyolcuepaliztli. netzinquixtiliztli.', ''),
