(3756, 7, 14, 40, '', '', '', '', '< Arrimar algo a otra cosa. > nitla,netechpachoa. tetech nitlapachoa. nitlanetechoa.', ''),
(3757, 7, 14, 41, '', '', '', '', '< Arrimada cosa assi. > tlanetechpacholli. tetech tlapacholli. tlanetecholli.', ''),
(3758, 7, 14, 42, '', '', '', '', '< Arrimador tal. > tlanetechpachoani. tetech tlapachoani. tlanetechoani.', ''),
(3759, 7, 14, 43, '', '', '', '', '< Arrimar o allegar tierra a algo. > nitla,tlalhuia.', ''),
(3760, 7, 14, 44, '', '', '', '', '< Arrimada tierra a algo. > tlatlalhuilli.', ''),
(3761, 7, 14, 45, '', '', '', '', '< Arrimar a la pared cosas largas. > caltech nic,quetza.', ''),
(3762, 7, 14, 46, '', '', '', '', '< Arrimada cosa assi. > caltech tlaquetztli.', ''),
(3763, 7, 14, 47, '', '', '', '', '< Arrimarse o echarse sobre otro. > tepan nino,tlaça. tetech nino,tlaça.', ''),
(3764, 7, 14, 48, '', '', '', '', '< Arrimado assi. > tetech motlazqui. tepam motlazqui.', ''),
(3765, 7, 14, 49, '', '', '', '', '< Arrimarme yo a otro. > tetech nino,pachoa. tetech nipachiui.', ''),
(3766, 7, 14, 50, '', '', '', '', '< Arroba. lo mesmo. >', ''),
(3767, 7, 14, 51, '', '', '', '', '< Arrobarse o trasportarse. > a yz uetzi(n) noyollo. a nic,yehuailhuia. a yzca noyollo.', ''),
(3768, 7, 14, 52, '', '', '', '', '< Arrodelarse. busca adargarse. > nino,chimalcaltia.', ''),
(3769, 7, 14, 53, '', '', '', '', '< Arrodillarse o hincarse de rodillas. > nino,tlanquaquetza.', ''),
(3770, 7, 14, 54, '', '', '', '', '< Arrodillado assi. > motlanquaquetzqui. motlanquaquetztica.', ''),
(3771, 7, 14, 55, '', '', '', '', '< Arrodillamiento. > netlanquaquetzaliztli.', ''),
