(3793, 7, 14, 77, '', '', '', '', '< Arrojar o empuxar a otro. > nite,topeua.', ''),
(3794, 7, 14, 78, '', '', '', '', '< Arrojado assi. > tlatopeuhtli.', ''),
(3795, 7, 14, 79, '', '', '', '', '< Arrojador tal. > tetopeuani.', ''),
(3796, 7, 14, 80, '', '', '', '', '< Arrojamiento assi. > tetopeualiztli.', ''),
