(3843, 7, 14, 127, '', '', '', '', '< Artista. > tlamatilizmatini.', ''),
(3844, 7, 14, 128, '', '', '', '', '< Asa de jarro. > vicollotl. tlauicollotl.', ''),
(3845, 7, 14, 129, '', '', '', '', '< Asabiendas. busca adrede. >', ''),
(3846, 7, 14, 130, '', '', '', '', '< Asabiendas y de voluntad hazer algo. > noyollo iuh yauh. noyollo tlama yn nicchiua noyollocopa yn nicchiua. niytztiuh in nicchiua.', ''),
