(3895, 7, 15, 30, '', '', '', '', '< Aspero y riscoso lugar. > texcalla. tetexcalla.', ''),
(3896, 7, 15, 31, '', '', '', '', '< Aspera y braua persona. > cocole. tlauele.', ''),
