(3910, 7, 15, 45, '', '', '', '', '< Assaeteador. > tecacalini. temiminani.', ''),
(3911, 7, 15, 46, '', '', '', '', '< Assaeteamiento. > tecacaliliztli. temiminaliztli.', ''),
(3912, 7, 15, 47, '', '', '', '', '< Assechar o acechar a otro. > ninote,pachiuia. nitla,neuiläuia. nite,tlatlacana. nite,tlatlacaauilana. [ni]note,pachiuia.', ''),
