(4283, 7, 17, 126, '', '', '', '', '< Auezindado assi. > monacti. monactiqui. motzico. motzicoqui.', ''),
(4284, 7, 17, 127, '', '', '', '', '< Auezindamiento tal. > nenactiliztli. netzicoliztli.', ''),
(4285, 7, 17, 128, '', '', '', '', '< Auisar a otro. > nite,nemachtia.', ''),
(4286, 7, 17, 129, '', '', '', '', '< Auisadamente. > tenemachtiliztica.', ''),
(4287, 7, 17, 130, '', '', '', '', '< Auisado de otro. > tlanemachitilli. tlanemachtilli.', ''),
(4288, 7, 17, 131, '', '', '', '', '< Auiso tal. > tenemachitiliztli. tenemachtiliztli.', ''),
(4289, 7, 17, 132, '', '', '', '', '< Auisar y aduertir al amigo de lo que le cöuiene hazer. > tiçatl yuitl, tlapalli nictlalia. tiçatl yuitl tlapalli nicchiua. ni,xonexca. nitla,matzoa.', ''),
