(4292, 7, 17, 135, '', '', '', '', '< Auiso tal. > tetenanauatiliztli. tetetlaqueuiliztli.', ''),
(4293, 7, 17, 136, '', '', '', '', '< Auisador assi. > tetenanauatiliani. tetlaqueuiani.', ''),
(4294, 7, 17, 137, '', '', '', '', '< Axedrez. > quappatolli.', ''),
(4295, 7, 17, 138, '', '', '', '', '< Axi o pimienta desta tierra. > chilli. { Azed }', ''),
(4296, 7, 18, 0, '', '', '$', '', '$FOLIO=18   { A ANTE Z. ET B ANTE A. 18 }', ''),
(4297, 7, 18, 1, '', '', '', '', '< Azeda cosa. > xococ.', ''),
(4298, 7, 18, 2, '', '', '', '', '< Azedarse algo. > xocoya.', ''),
(4299, 7, 18, 3, '', '', '', '', '< Azedia. > xocoyaliztli.', ''),
(4300, 7, 18, 4, '', '', '', '', '< Azedar alguna cosa. > nitla,xocolia.', ''),
(4301, 7, 18, 5, '', '', '', '', '< Azedera, yerua agra. > xocoyolli. xoxocoyolli. xocoyolpapatla. tepexocoyolli. xuxucuyulli.', ''),
