(4311, 7, 18, 15, '', '', '', '', '< Azeite de pepitas. > ayuuachiauacayotl. aouachazeite.', ''),
(4312, 7, 18, 16, '', '', '', '', '< Azeite de almendras. > almendras chiauacayotl. almendras azeite.', ''),
(4313, 7, 18, 17, '', '', '', '', '< Azeite de nuezes. > nuezes chiauacayotl.', ''),
(4314, 7, 18, 18, '', '', '', '', '< Azeite de vallena. > vei michiauacayotl.', ''),
(4315, 7, 18, 19, '', '', '', '', '< Azeite rosado. > rosas azeite. xuchiazeite.', ''),
(4316, 7, 18, 20, '', '', '', '', '< Azeitosa cosa. > azeiteyo. chiauiço.', ''),
