(4322, 7, 18, 26, '', '', '', '', '< Azogue. > yuli amuchitl.', ''),
(4323, 7, 18, 27, '', '', '', '', '< Azul, color. > texutli.', ''),
(4324, 7, 18, 28, '', '', '', '', '< Azul mas fino. > matlalin. matlaltic.', ''),
