(4332, 7, 18, 36, '', '', '', '', '< Baçucad a cosa. > tlacocoxonilli.', ''),
(4333, 7, 18, 37, '', '', '', '', '< Baçucador. > tlacocoxoniani.', ''),
(4334, 7, 18, 38, '', '', '', '', '< Baçucadura. > tlacocoxoniliztli.', ''),
