(4339, 7, 18, 43, '', '', '', '', '< Baho. > ypotoctli. yhiotl.', ''),
(4340, 7, 18, 44, '', '', '', '', '< Baho que sale del agua. > apoctli.', ''),
(4341, 7, 18, 45, '', '', '', '', '< Baho que sale de la tierra. > tlalpotoctli.', ''),
(4342, 7, 18, 46, '', '', '', '', '< Baho del cuerpo humano. > tlacaipotoctli.', ''),
(4343, 7, 18, 47, '', '', '', '', '< Baho de la boca. > tihio. yhiotl.', ''),
(4344, 7, 18, 48, '', '', '', '', '< Bailar o dançar. > nin,itotia. ni,maceua.', ''),
(4345, 7, 18, 49, '', '', '', '', '< Bailador. > mitotiani. maceua(u)[n]i.', ''),
