(4467, 7, 19, 7, '', '', '', '', '< Batanar. > nitla,paca.', ''),
(4468, 7, 19, 8, '', '', '', '', '< Batanado. > tlapactli.', ''),
(4469, 7, 19, 9, '', '', '', '', '< Batata. fruta conocida. > camotli.', ''),
(4470, 7, 19, 10, '', '', '', '', '< Batea. > quauhxicalli.', ''),
