(4590, 7, 19, 130, '', '', '', '', '< ¶Biboreznos. > tequancoacocone.', ''),
(4591, 7, 19, 131, '', '', '', '', '< Bien, nombre. > qualli. yectli.', ''),
(4592, 7, 19, 132, '', '', '', '', '< Bien. > uel. {Aduerbio.}', ''),
