(4598, 7, 19, 138, '', '', '', '', '< Bienes de furtuna. > tlatquitl.', ''),
(4599, 7, 19, 139, '', '', '', '', '< Bien esta. busca abasta. >', ''),
(4600, 7, 19, 140, '', '', '', '', '< Bië estar o quadrar algo a alguno. > nechmopanitia', ''),
(4601, 7, 19, 141, '', '', '', '', '< Bien esta, otorgando. > maiui. ye qualli. < Y las mugeres dizen. > xiço. xiçotzi.', ''),
