(4605, 7, 19, 145, '', '', '', '', '< Bien hechor. > teicneliani. tetlauhtiani.', ''),
(4606, 7, 19, 146, '', '', '', '', '< Bien q~rer. busca amar. >', ''),
(4607, 7, 19, 147, '', '', '', '', '< Bien quisto. > vel ittoni. tlauelittalli.', ''),
(4608, 7, 19, 148, '', '', '', '', '< Bien se dize del. > vel ipan yauh yn tlatolli.', ''),
