(4628, 7, 19, 168, '', '', '', '', '< Biuo de entendimiento. > yollo. yolizmatqui. mozcaliani.', ''),
(4629, 7, 19, 169, '', '', '', '', '< Biuora generalmente. > tequani coatl. { Biuora }', ''),
(4630, 7, 20, 0, '', '', '$', '', '$FOLIO=20   { B ANTE I, L, ET O. 20 }', ''),
(4631, 7, 20, 1, '', '', '', '', '< Biuora muy ponçoñosa y grande. > tecutlacoçauhqui.', ''),
(4632, 7, 20, 2, '', '', '', '', '< Biuora blanca y larga. > yztac coatl.', ''),
(4633, 7, 20, 3, '', '', '', '', '< Biuora otra pestilencial y de gran ponçoña. > cotoccoatl.', ''),
(4634, 7, 20, 4, '', '', '', '', '< Biuora negra. > tlilcoatl.', ''),
(4635, 7, 20, 5, '', '', '', '', '< Biuoras otras. > chiauhcoatl. chiauitl. çolcoatl.', ''),
(4636, 7, 20, 6, '', '', '', '', '< Biuorezno. > tequancoaconetl. tequani coaconetl. tecutlacuçauhcoaconetl.', ''),
(4637, 7, 20, 7, '', '', '', '', '< Biuoreznos. > tequancoacocone. tequani coacocone. tecutlacoçauhcoacocone.', ''),
(4638, 7, 20, 8, '', '', '', '', '< Bizma o bidma. > nepotoniloni.', ''),
(4639, 7, 20, 9, '', '', '', '', '< Bizma poner a otro. > nite,potonia.', ''),
(4640, 7, 20, 10, '', '', '', '', '< Blanca cosa. > yztac. teztic.', ''),
(4641, 7, 20, 11, '', '', '', '', '< Blanca cosa, en gran manera. > aztapiltic. yztapatic. tezcuitlatic. cenca yztac. yuhqui ichcatlapuchintli yc iztac. yuhquin cepayauitl yc iztac. yuhqui tiçatl yc iztac. {&c.}', ''),
