(4647, 7, 20, 17, '', '', '', '', '< Blanquezino assi. > yztalectic. ciocopictic.', ''),
(4648, 7, 20, 18, '', '', '', '', '< Blancura tal. > yztalectiliztli. ciocopinaliztli.', ''),
(4649, 7, 20, 19, '', '', '', '', '< Blancura o lo blanco de los ojos. > toztacauh.', ''),
(4650, 7, 20, 20, '', '', '', '', '< Blancura tal. > yztacayotl.', ''),
