(4668, 7, 20, 38, '', '', '', '', '< Blanqueador assi. > tlaztaliani.', ''),
(4669, 7, 20, 39, '', '', '', '', '< Blanqueada cosa desta manera. > tlaztalilli.', ''),
(4670, 7, 20, 40, '', '', '', '', '< Blanqueamiento assi. > tlaztaliliztli.', ''),
(4671, 7, 20, 41, '', '', '', '', '< Blanquizca cosa y deslauada. > ticectic. ticeuac.', ''),
